(() => {
'use strict';
const E=window.DragonEngine;
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const attr=esc;const pct=(n,d)=>Math.max(0,Math.min(100,d?Number(n)/Number(d)*100:0));
const clone=v=>structuredClone(v);const now=()=>new Date().toISOString();
const STORE='dragon-saga-campaign-v2.2';
const MAPS=[
 {id:'full',name:'Полный атлас Севера',src:'/world/north_full_atlas.jpg',desc:'Земли людей, эльфов и дварфов в единой панораме.'},
 {id:'humans',name:'Земли людей',src:'/world/north_humans.jpg',desc:'Нортвинд, Остюр, Бергхейм и дороги человеческих владений.'},
 {id:'elves',name:'Земли эльфов',src:'/world/north_elves.jpg',desc:'Ринхолд, Эхуил, Амон Анго и древние лесные пути.'},
 {id:'dwarves',name:'Земли дварфов',src:'/world/north_dwarves.jpg',desc:'Зирак-дум и горные дороги северных кланов.'}
];
const LOCATIONS=['Нортвинд','Остюр','Бергхейм','Ринхолд','Эхуил','Амон Анго','Зирак-дум','Орочье поселение','Храм трёх скрижалей','Утун','Ангмунд'];
const ZONES={t1:{code:'Т1',name:'Тыл героев',side:'hero',rear:true},a1:{code:'А1',name:'Авангард героев',side:'hero'},a2:{code:'А2',name:'Авангард врагов',side:'enemy'},t2:{code:'Т2',name:'Тыл врагов',side:'enemy',rear:true}};
const ZONE_ORDER=['t1','a1','a2','t2'];
const CONDITIONS=['ослеплён','очарован','оглушён','испуган','схвачен','недееспособен','невидим','парализован','окаменел','отравлен','сбит с ног','опутан','истощение'];
let currentView='dashboard',selectedCharacterId=null,selectedMap='full',contextTab='actions',mediaTab='all',workshopTab='creatures',selectedSceneId=null,sceneAssetId=null,modalHandler=null,saveTimer=null,net=null,renderQueued=false,modelRuntimePromise=null;

function baseState(){return{
 schema:'dragon-saga-campaign',version:3,meta:{title:'Новая сага',createdAt:now(),updatedAt:now(),edition:'2024'},
 session:{clientId:E.id(),name:'Мастер',role:'gm',characterId:null,roomCode:'',token:'',ownerKey:'',connected:false,members:[]},
 permissions:{mediaEditors:[],partySheetView:true,playerJournalShared:false},settings:{uiScale:1,battleScale:1,modelScale:1,panelScale:1,autosave:true,language:'ru',theme:{accent:'#a8423c',gold:'#b49a6d'},animation:{idleDuration:3.2},localization:{}},
 characters:[],journal:{party:'',chronicle:[],personal:{}},
 world:{maps:MAPS.map(x=>({...x})),locations:LOCATIONS.map((name,i)=>({id:E.id(),name,description:'',discovered:i<7,gmNotes:''})),routes:[]},
 cities:[],assets:[],scenes:[],content:{items:[],actions:[],creatures:[],mods:[]},
 battle:{active:false,round:1,turnIndex:0,order:[],positions:{},movement:{},turnStartZones:{},flags:{},targetId:null,sceneId:null,result:null,log:[]}
}}
function normalize(raw){const b=baseState();if(!raw||raw.schema!==b.schema)return b;const s={...b,...raw};s.meta={...b.meta,...raw.meta};s.session={...b.session,...raw.session,connected:false,members:[]};s.permissions={...b.permissions,...raw.permissions};s.settings={...b.settings,...raw.settings};s.journal={...b.journal,...raw.journal,personal:{...b.journal.personal,...raw.journal?.personal}};s.world={...b.world,...raw.world};s.content={...b.content,...raw.content};s.battle={...b.battle,...raw.battle,positions:{...raw.battle?.positions},movement:{...raw.battle?.movement},turnStartZones:{...raw.battle?.turnStartZones},flags:{...raw.battle?.flags},log:[...(raw.battle?.log||[])].slice(-150)};s.characters=(raw.characters||[]).map(c=>({...E.blankCharacter(c.role),...c,stats:{...E.blankCharacter().stats,...c.stats},deathSaves:{success:0,fail:0,...c.deathSaves},equipment:{...E.blankCharacter().equipment,...c.equipment},currency:{gp:0,sp:0,cp:0,...c.currency},hitDice:{die:8,current:1,max:1,...c.hitDice}}));return s}
let state=(()=>{try{return normalize(JSON.parse(localStorage.getItem(STORE)))}catch{return baseState()}})();
function isGM(){return state.session.role==='gm'}function ownCharacter(){return state.characters.find(c=>c.id===state.session.characterId)||null}function canEditCharacter(c){return isGM()||c?.id===state.session.characterId}function canEditMedia(){return isGM()||state.permissions.mediaEditors.includes(state.session.clientId)}
function setDirty(){state.meta.updatedAt=now();$('#autosaveLabel').textContent='СОХРАНЕНИЕ…';$('#autosaveLabel').classList.add('saving');clearTimeout(saveTimer);saveTimer=setTimeout(saveLocal,300)}
function saveLocal(){try{localStorage.setItem(STORE,JSON.stringify(state));$('#autosaveLabel').textContent='✓ СОХРАНЕНО';$('#autosaveLabel').classList.remove('saving');if(state.session.connected)pushRoom()}catch(err){toast('Не удалось сохранить',err.message)} }
function commit(message,rerender=true){setDirty();if(message)toast('Готово',message);if(rerender)render()}
function toast(title,text=''){const el=document.createElement('div');el.className='toast';el.innerHTML=`<b>${esc(title)}</b>${text?`<br>${esc(text)}`:''}`;$('#toastHost').append(el);setTimeout(()=>el.remove(),4200)}
function applyScales(){const root=$('#app');for(const k of ['uiScale','battleScale','modelScale','panelScale'])root.style.setProperty(`--${k.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}`,state.settings[k]);const color=v=>/^#[0-9a-f]{3,8}$/i.test(String(v))?v:null;root.style.setProperty('--accent',color(state.settings.theme?.accent)||'#a8423c');root.style.setProperty('--gold',color(state.settings.theme?.gold)||'#b49a6d');root.style.setProperty('--idle-duration',`${E.clamp(state.settings.animation?.idleDuration||3.2,1,10)}s`)}
function applyLocalization(){const dict=state.settings.localization||{};if(!Object.keys(dict).length||!document.createTreeWalker||!document.body)return;const walker=document.createTreeWalker(document.body,globalThis.NodeFilter?.SHOW_TEXT||4);let n;while((n=walker.nextNode())){const key=n.nodeValue.trim();if(key&&dict[key])n.nodeValue=n.nodeValue.replace(key,String(dict[key]))}}
function initials(name){return String(name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function portraitStyle(c){const a=state.assets.find(x=>x.id===c.portraitAsset);return a?.data?`style="background-image:url('${attr(a.data)}')"`:''}
function heading(kicker,title,desc,actions=''){return `<div class="view-heading"><div><span class="section-kicker">${esc(kicker)}</span><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="heading-actions">${actions}</div></div>`}
function empty(icon,title,text,button=''){return `<div class="empty-state"><div class="rune">${icon}</div><h2>${esc(title)}</h2><p>${esc(text)}</p>${button}</div>`}
function modal(title,subtitle,body,actions='',wide=false,handler=null){modalHandler=handler;$('#modalHost').innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><header class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="modal-close" data-close>×</button></header><div class="modal-body">${body}</div>${actions?`<footer class="modal-actions">${actions}</footer>`:''}</section></div>`;$('.modal-backdrop').addEventListener('click',e=>{if(e.target.hasAttribute('data-close-modal'))closeModal()})}
function closeModal(){modalHandler=null;$('#modalHost').innerHTML=''}
function formField(label,id,value='',type='text',extra=''){return `<label class="form-field"><span>${esc(label)}</span><input class="text-input" id="${id}" type="${type}" value="${attr(value)}" ${extra}></label>`}
function selectField(label,id,options,value,extra=''){return `<label class="form-field"><span>${esc(label)}</span><select class="select" id="${id}" ${extra}>${options.map(([v,t])=>`<option value="${attr(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}

function shellSync(){applyScales();$('#campaignTitle').innerHTML=`${esc(state.meta.title)} <span>✎</span>`;$$('[data-edition]').forEach(b=>b.classList.toggle('active',b.dataset.edition===state.meta.edition));$('#roleBadge').textContent=isGM()?'МАСТЕР':'ИГРОК';$('#roleHint').textContent=isGM()?'полный контроль стола':'управление своим героем';$('#profileBtn').textContent=initials(state.session.name);$('#characterNavLabel').textContent=isGM()?'Персонажи':'Мой герой';$('#navCharacters').textContent=`${state.characters.filter(x=>x.role==='hero').length} ЛИСТОВ`;$('#navRound').textContent=`РАУНД ${state.battle.round}`;$$('[data-gm-only]').forEach(x=>x.hidden=!isGM());$$('[data-editor-only]').forEach(x=>x.hidden=!canEditMedia());$('#syncStatus').classList.toggle('live',state.session.connected);$('#syncStatus span').textContent=state.session.connected?`Стол ${state.session.roomCode}`:'Локальная кампания';$('#roomBtn').classList.toggle('live',state.session.connected);}
function render(){if(renderQueued)return;renderQueued=true;requestAnimationFrame(()=>{renderQueued=false;shellSync();$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));const views={dashboard:renderDashboard,battle:renderBattle,characters:renderCharacters,journal:renderJournal,world:renderWorld,cities:renderCities,scene:renderScenes,library:renderLibrary,photo:renderPhoto,workshop:renderWorkshop,rules:renderRules};$('#mainContent').innerHTML=(views[currentView]||renderDashboard)();if(currentView==='photo'){window.DragonSagaImageEditor?.mount?.($('#mainContent'))}bindDynamic();applyLocalization();})}
function heroSummary(c){return `<article class="hero-summary"><div class="portrait-mini" ${portraitStyle(c)}>${state.assets.find(x=>x.id===c.portraitAsset)?'':esc(initials(c.name))}</div><div><b>${esc(c.name)}</b><small>${esc([c.race,c.className,c.level?`${c.level} ур.`:''].filter(Boolean).join(' · ')||'Лист не заполнен')}</small></div><div><span class="number-line">ОЗ ${c.hp}/${c.maxHp}${c.tempHp?` +${c.tempHp}`:''}</span><div class="hp-meter"><i style="width:${pct(c.hp,c.maxHp)}%"></i></div></div><div class="summary-resources">${(c.resources||[]).slice(0,3).map(r=>`<span>${esc(r.name)} ${r.current}/${r.max}</span>`).join('')||'<span>нет ресурсов</span>'}</div><button class="small" data-character="${c.id}">Открыть</button></article>`}
function renderDashboard(){const heroes=state.characters.filter(c=>c.role==='hero');const own=ownCharacter();const shown=isGM()?heroes:(own?[own]:[]);const active=currentActor();return `<section class="view">${heading(isGM()?'СТОЛ МАСТЕРА':'ЛИЧНЫЙ СТОЛ',isGM()?'Обзор кампании':(own?.name||'Персонаж не назначен'),isGM()?'Состояние группы, текущий бой и быстрые инструменты без лишней перегрузки.':'Ваш лист, ресурсы, записи и разрешённые действия собраны в одном месте.',isGM()?'<button class="red-btn" data-action="new-character">＋ Создать героя</button>':'')}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>${isGM()?'Группа':'Мой герой'}</h2><small>${shown.length} ДОСТУПНО</small></div><div class="party-overview">${shown.length?shown.map(heroSummary).join(''):empty('♙',isGM()?'Группа пока пуста':'Герой не назначен',isGM()?'Создайте героя вручную или импортируйте точный текст статблока.':'Попросите мастера назначить вам персонажа.','')}</div></section><aside class="panel"><div class="panel-head"><h2>Сводка</h2><small>СЕЙЧАС</small></div><div class="quick-ledger"><div class="ledger-item"><small>РЕДАКЦИЯ</small><strong>5E · ${state.meta.edition}</strong></div><div class="ledger-item"><small>БОЙ</small><strong>${state.battle.active?`Раунд ${state.battle.round}`:'Не начат'}</strong>${active?`<span>${esc(active.name)} ходит</span>`:''}</div><div class="ledger-item"><small>МИР</small><strong>${state.world.routes.length}</strong><span>маршрутов создано</span></div><div class="ledger-item"><small>ХРОНИКА</small><strong>${state.journal.chronicle.length}</strong><span>записей</span></div></div></aside></div></section>`}

function availableCharacters(){if(isGM())return state.characters;const own=ownCharacter();return state.characters.filter(c=>c.id===own?.id||(state.permissions.partySheetView&&c.role==='hero'&&c.visibility!=='private'))}
function renderCharacters(){let chars=availableCharacters();if(!isGM()&&ownCharacter())chars=[ownCharacter(),...chars.filter(c=>c.id!==ownCharacter().id)];if(!selectedCharacterId||!chars.some(c=>c.id===selectedCharacterId))selectedCharacterId=chars[0]?.id||null;const selected=chars.find(c=>c.id===selectedCharacterId);const actions=isGM()?'<button class="outline-btn" data-action="import-character">Импорт текста</button><button class="red-btn" data-action="new-character">＋ Новый лист</button>':'';return `<section class="view">${heading('ЛИСТЫ 5E',isGM()?'Персонажи и противники':'Персонаж','Исходный текст импорта всегда хранится дословно. Распознанные поля отмечаются аудитом, а любые правки остаются под контролем владельца.',actions)}${chars.length?`<div class="character-layout"><div class="character-list">${chars.map(c=>`<button class="character-card ${c.id===selectedCharacterId?'selected':''}" data-select-character="${c.id}"><div class="portrait" ${portraitStyle(c)}>${state.assets.find(x=>x.id===c.portraitAsset)?'':esc(initials(c.name))}</div><b>${esc(c.name)}</b><small>${c.role==='enemy'?'ПРОТИВНИК':c.id===state.session.characterId?'МОЙ ГЕРОЙ':'ГЕРОЙ'} · КД ${c.ac}</small><div class="hp-meter"><i style="width:${pct(c.hp,c.maxHp)}%"></i></div><span>${c.hp}/${c.maxHp} ОЗ</span></button>`).join('')}</div>${selected?renderSheet(selected):''}</div>`:empty('♙','Нет доступных листов',isGM()?'Создайте пустой лист или импортируйте статблок без потери исходного текста.':'Мастер ещё не назначил героя или не открыл листы группы.',isGM()?'<button class="red-btn" data-action="new-character">Создать первый лист</button>':'')}</section>`}
function renderSheet(c){const edit=canEditCharacter(c);return `<article class="sheet"><div class="sheet-hero"><div class="portrait" ${portraitStyle(c)}>${state.assets.find(x=>x.id===c.portraitAsset)?'':esc(initials(c.name))}</div><div><span class="section-kicker">${c.role==='enemy'?'ПРОТИВНИК':'ПЕРСОНАЖ'}</span><h2>${esc(c.name)}</h2><p>${esc([c.race,c.className,c.level&&`${c.level} уровень`].filter(Boolean).join(' · ')||'Описание не заполнено')}</p><div class="rule-tags"><span>скорость ${c.speed} фт</span><span>мастерство +${c.proficiency}</span>${c.conditions.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><div class="shield"><small>КД</small><b>${c.ac}</b></div></div><div class="sheet-tabs"><button class="active">Лист</button><button data-action="show-source" data-id="${c.id}">Исходник</button><button data-action="show-audit" data-id="${c.id}">Аудит</button></div><div class="sheet-grid"><section class="stat-card"><small>ХИТЫ</small><strong>${c.hp} / ${c.maxHp}</strong><div class="hp-meter"><i style="width:${pct(c.hp,c.maxHp)}%"></i></div>${edit?`<div class="editor-button-row"><button class="small" data-hp="-1" data-id="${c.id}">−1</button><button class="small" data-hp="1" data-id="${c.id}">+1</button></div>`:''}</section><section class="stat-card"><small>ИНИЦИАТИВА</small><strong>${E.signed(c.initiative)}</strong></section><section class="stat-card"><small>КОСТИ ХИТОВ</small><strong>${c.hitDice.current}/${c.hitDice.max}к${c.hitDice.die}</strong></section><section class="stat-card"><small>ЗАКЛИНАНИЯ</small><strong>${c.spellDC?`Сл ${c.spellDC}`:'—'}</strong></section></div><div class="ability-grid">${E.ABILITIES.map(k=>`<div class="ability"><small>${E.ABILITY_RU[k]}</small><b>${c.stats[k]}</b><span>${E.signed(E.abilityMod(c.stats[k]))}</span></div>`).join('')}</div><section class="surface"><div class="section-head"><h2>Действия</h2>${edit?`<button class="small" data-action="new-action" data-id="${c.id}">＋ действие</button>`:''}</div><div class="action-list">${c.actions.length?c.actions.map(a=>`<div class="action-button"><div><b>${esc(a.name)}</b><small>${esc(E.actionDetail(a))}</small></div>${edit?`<button class="small" data-action="edit-action" data-char="${c.id}" data-id="${a.id}">Изм.</button>`:''}</div>`).join(''):'<p class="micro">Действий пока нет.</p>'}</div></section><section class="surface"><div class="section-head"><h2>Ресурсы</h2>${edit?`<button class="small" data-action="new-resource" data-id="${c.id}">＋ ресурс</button>`:''}</div><div class="resource-list">${c.resources.length?c.resources.map(r=>`<div class="resource-row"><div><b>${esc(r.name)}</b><small>${esc(r.recovery)} отдых</small></div><div><button class="small" ${edit?'':'disabled'} data-resource="-1" data-char="${c.id}" data-id="${r.id}">−</button> <span>${r.current}/${r.max}</span> <button class="small" ${edit?'':'disabled'} data-resource="1" data-char="${c.id}" data-id="${r.id}">+</button></div></div>`).join(''):'<p class="micro">Нет ограниченных ресурсов.</p>'}</div></section><section class="surface"><div class="section-head"><h2>Инвентарь и снаряжение</h2><span class="tag">${c.currency.gp} зм · ${c.currency.sp} см · ${c.currency.cp} мм</span>${edit&&(!state.session.connected||isGM())?`<button class="small" data-action="new-item" data-id="${c.id}">＋ предмет</button>`:''}</div><div class="inventory-list">${c.inventory.length?c.inventory.map(i=>`<div class="inventory-row"><div><b>${esc(i.name)}</b><small>${i.quantity||1} шт.${i.equippedSlot?` · ${esc(i.equippedSlot)}`:''}${i.value?` · ${i.value} зм`:''}</small></div>${edit?`<button class="small" data-action="edit-item" data-char="${c.id}" data-id="${i.id}">Изм.</button>`:''}</div>`).join(''):'<p class="micro">Инвентарь пуст.</p>'}</div><div class="rule-tags"><span>Доспех: ${esc(c.inventory.find(i=>i.id===c.equipment.armor)?.name||'—')}</span><span>Основная рука: ${esc(c.inventory.find(i=>i.id===c.equipment.mainHand)?.name||'—')}</span><span>Вторая рука: ${esc(c.inventory.find(i=>i.id===c.equipment.offHand)?.name||'—')}</span><span>Аксессуар: ${esc(c.inventory.find(i=>i.id===c.equipment.accessory)?.name||'—')}</span></div></section>${edit?`<div class="heading-actions"><button class="outline-btn" data-action="edit-character" data-id="${c.id}">Редактировать лист</button>${isGM()?`<button class="danger-btn" data-action="delete-character" data-id="${c.id}">Удалить</button>`:''}</div>`:''}</article>`}

function openCharacterEditor(c=null){const fresh=!c,networkPlayer=state.session.connected&&!isGM();if(fresh&&networkPlayer)return toast('Только мастер создаёт листы в сетевой комнате');c=c?clone(c):E.blankCharacter('hero');modal(fresh?'Новый лист':'Редактирование листа','Пустая кампания ничего не навязывает: все значения задаёте вы.',`<div class="form-grid">${formField('Имя','ceName',c.name)}${selectField('Сторона','ceRole',[['hero','Герой'],['enemy','Противник']],c.role,networkPlayer?'disabled':'')}${formField('Класс / тип','ceClass',c.className)}${formField('Раса / вид','ceRace',c.race)}${formField('Уровень','ceLevel',c.level,'number','min="0" max="30"')}${formField('КД','ceAc',c.ac,'number','min="0"')}${formField('Текущие ОЗ','ceHp',c.hp,'number','min="0"')}${formField('Максимум ОЗ','ceMaxHp',c.maxHp,'number','min="1"')}${formField('Скорость, фт','ceSpeed',c.speed,'number','min="0" step="5"')}${formField('Масштаб модели, %','ceScale',c.modelScale,'number','min="25" max="250"')}${selectField('Портрет','cePortrait',[['','Без портрета'],...state.assets.filter(a=>a.kind==='image').map(a=>[a.id,a.name])],c.portraitAsset||'')}${selectField('Полноразмерная модель / PNG','ceToken',[['','Без модели'],...state.assets.filter(a=>a.kind==='image').map(a=>[a.id,a.name])],c.tokenAsset||'')}${formField('Золото, зм','ceGP',c.currency.gp,'number',`min="0" step="0.01" ${networkPlayer?'disabled title="В сети валюту изменяют торговля и мастер"':''}`)}${formField('Состояния через запятую','ceConditions',c.conditions.join(', '))}<label class="form-field"><span><input id="ceBoss" type="checkbox" ${c.boss?'checked':''} ${networkPlayer?'disabled':''}> босс с телеграфами</span></label> ${E.ABILITIES.map(k=>formField(E.ABILITY_RU[k],`ce-${k}`,c.stats[k],'number','min="1" max="30"')).join('')}<label class="form-field full"><span>Заметки</span><textarea class="text-area" id="ceNotes">${esc(c.notes)}</textarea></label></div>`,`<button class="dark-btn" data-close>Отмена</button><div class="modal-actions-right"><button class="primary" data-modal-submit>Сохранить</button></div>`,false,()=>{c.name=$('#ceName').value.trim()||'Безымянный';c.role=$('#ceRole').value;c.className=$('#ceClass').value.trim();c.race=$('#ceRace').value.trim();for(const [k,id,min] of [['level','ceLevel',0],['ac','ceAc',0],['hp','ceHp',0],['maxHp','ceMaxHp',1],['speed','ceSpeed',0],['modelScale','ceScale',25]])c[k]=Math.max(min,Number($('#'+id).value)||min);for(const k of E.ABILITIES)c.stats[k]=E.clamp($('#ce-'+k).value,1,30);c.notes=$('#ceNotes').value;c.portraitAsset=$('#cePortrait').value||null;c.tokenAsset=$('#ceToken').value||null;c.currency.gp=Math.max(0,Number($('#ceGP').value)||0);c.conditions=$('#ceConditions').value.split(',').map(x=>x.trim()).filter(Boolean);c.boss=$('#ceBoss').checked;if(fresh){state.characters.push(c);selectedCharacterId=c.id}else Object.assign(state.characters.find(x=>x.id===c.id),c);closeModal();commit(fresh?'Лист создан':'Лист обновлён')})}
function openImport(){modal('Импорт статблока','Система извлекает только явно найденные значения. Полный исходник сохраняется дословно для сверки.',`<div class="help-callout">Поддерживаются русские и английские подписи: КД/AC, Хиты/HP, СИЛ/STR, ресурсы 2/2, атаки, формулы урона и спасброски. Неуказанные данные не додумываются.</div><label class="form-field"><span>Текст листа или статблока</span><textarea id="importText" class="text-area" style="min-height:330px" placeholder="Имя: ...&#10;КД: ...&#10;Хиты: ..."></textarea></label><div id="importPreview"></div>`,`<button class="dark-btn" data-close>Отмена</button><div class="modal-actions-right"><button class="outline-btn" data-action="preview-import">Проверить</button><button class="primary" data-modal-submit>Импортировать</button></div>`,true,()=>{const text=$('#importText').value;if(!text.trim())return toast('Нужен текст');const {character,warnings}=E.parseCharacterText(text,state.meta.edition);state.characters.push(character);selectedCharacterId=character.id;closeModal();commit(`Импортировано. Предупреждений: ${warnings.length}`)})}
function openActionEditor(charId,actionId=null){const c=state.characters.find(x=>x.id===charId);if(!c)return;let a=actionId?clone(c.actions.find(x=>x.id===actionId)):{id:E.id(),name:'Новое действие',type:'attack',kind:'melee',cost:'action',attackBonus:0,damage:'1d6',damageType:'',saveAbility:null,saveDC:null,halfOnSave:false,currentUses:null,maxUses:null,recovery:'long',targetSide:'enemy',notes:''};modal(actionId?'Изменить действие':'Новое действие','Один клик выполнит бросок атаки, урона или спасброска по выбранной цели.',`<div class="form-grid">${formField('Название','aeName',a.name)}${selectField('Тип','aeType',[['attack','Атака'],['spell','Атака заклинанием'],['save','Спасбросок цели'],['damage','Автоматический урон'],['heal','Лечение'],['utility','Особое']],a.type)}${selectField('Дистанция','aeKind',[['melee','Ближняя'],['ranged','Дальняя']],a.kind)}${selectField('Цена действия','aeCost',[['action','Действие'],['bonus','Бонусное действие'],['reaction','Реакция'],['free','Свободное']],a.cost||'action')}${selectField('Цель','aeTarget',[['enemy','Враг'],['ally','Союзник'],['self','Сам персонаж']],a.targetSide||'enemy')}${formField('Бонус атаки','aeAttack',a.attackBonus??'','number')}${formField('Формула урона / лечения','aeDamage',a.damage)}${formField('Тип урона','aeDamageType',a.damageType)}${selectField('Характеристика спасброска','aeSave',[['','—'],...E.ABILITIES.map(k=>[k,E.ABILITY_RU[k]])],a.saveAbility||'')}${formField('Сл','aeDC',a.saveDC??'','number')}${formField('Использований осталось','aeCurrent',a.currentUses??'','number','min="0"')}${formField('Максимум использований','aeMax',a.maxUses??'','number','min="0"')}<label class="form-field full"><span>Описание</span><textarea class="text-area" id="aeNotes">${esc(a.notes)}</textarea></label></div>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Сохранить</button>`,false,()=>{a.name=$('#aeName').value.trim()||'Действие';a.type=$('#aeType').value;a.kind=$('#aeKind').value;a.cost=$('#aeCost').value;a.targetSide=$('#aeTarget').value;a.attackBonus=$('#aeAttack').value===''?null:Number($('#aeAttack').value);a.damage=$('#aeDamage').value.trim();a.damageType=$('#aeDamageType').value.trim().toLowerCase();a.saveAbility=$('#aeSave').value||null;a.saveDC=$('#aeDC').value===''?null:Number($('#aeDC').value);a.currentUses=$('#aeCurrent').value===''?null:Number($('#aeCurrent').value);a.maxUses=$('#aeMax').value===''?null:Number($('#aeMax').value);a.notes=$('#aeNotes').value;if(actionId)Object.assign(c.actions.find(x=>x.id===actionId),a);else c.actions.push(a);closeModal();commit('Действие сохранено')})}
function openResourceEditor(charId){const c=state.characters.find(x=>x.id===charId);if(!c)return;modal('Новый ресурс',c.name,`<div class="form-grid">${formField('Название','reName','Новый ресурс')}${formField('Текущее значение','reCurrent',1,'number','min="0"')}${formField('Максимум','reMax',1,'number','min="1"')}${selectField('Восстановление','reRecovery',[['short','Короткий отдых'],['long','Долгий отдых'],['dawn','На рассвете'],['round','Каждый раунд']], 'long')}</div>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Добавить</button>`,false,()=>{const max=Math.max(1,Number($('#reMax').value)||1);c.resources.push({id:E.id(),name:$('#reName').value.trim()||'Ресурс',current:E.clamp($('#reCurrent').value,0,max),max,recovery:$('#reRecovery').value});closeModal();commit('Ресурс добавлен')})}
function openItemEditor(charId,itemId=null){const c=state.characters.find(x=>x.id===charId);if(!c)return;const fresh=!itemId,networkLocked=state.session.connected&&!isGM();if(fresh&&networkLocked)return toast('В сетевой комнате новые предметы добавляют мастер или торговля');let i=fresh?{id:E.id(),name:'Новый предмет',quantity:1,weight:0,value:0,description:'',equippedSlot:''}:clone(c.inventory.find(x=>x.id===itemId));if(!i)return;modal(fresh?'Новый предмет':'Предмет',c.name,`<div class="form-grid">${formField('Название','itName',i.name)}${formField('Количество','itQty',i.quantity||1,'number',`min="0" ${networkLocked?'disabled':''}`)}${formField('Вес одной единицы','itWeight',i.weight||0,'number','min="0" step="0.1"')}${formField('Стоимость, зм','itValue',i.value||0,'number','min="0" step="0.01"')}${selectField('Снаряжение','itSlot',[['','Не экипирован'],['armor','Доспех'],['mainHand','Основная рука'],['offHand','Вторая рука'],['accessory','Аксессуар']],i.equippedSlot||'')}</div><label class="form-field"><span>Описание</span><textarea class="text-area" id="itDesc">${esc(i.description||'')}</textarea></label>`,`<button class="danger-btn" data-action="delete-item" data-char="${c.id}" data-id="${i.id}" ${fresh||networkLocked?'disabled':''}>Удалить</button><div class="modal-actions-right"><button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Сохранить</button></div>`,false,()=>{i.name=$('#itName').value.trim()||'Предмет';i.quantity=Math.max(0,Number($('#itQty').value)||0);i.weight=Math.max(0,Number($('#itWeight').value)||0);i.value=Math.max(0,Number($('#itValue').value)||0);i.description=$('#itDesc').value;i.equippedSlot=$('#itSlot').value;for(const slot of Object.keys(c.equipment))if(c.equipment[slot]===i.id)c.equipment[slot]=null;if(i.equippedSlot)c.equipment[i.equippedSlot]=i.id;if(fresh)c.inventory.push(i);else Object.assign(c.inventory.find(x=>x.id===i.id),i);closeModal();commit('Инвентарь обновлён')})}
function combatants(){return state.battle.order.map(id=>state.characters.find(c=>c.id===id)).filter(Boolean)}function currentActor(){return state.characters.find(c=>c.id===state.battle.order[state.battle.turnIndex])||null}function sideOf(c){return c?.role==='enemy'?'enemy':'hero'}
function battlePosition(id){return state.battle.positions[id]||null}function inFriendlyRear(c,zone){return (sideOf(c)==='hero'&&zone==='t1')||(sideOf(c)==='enemy'&&zone==='t2')}function friendlyVanguard(c){return sideOf(c)==='hero'?'a1':'a2'}function enemyVanguard(c){return sideOf(c)==='hero'?'a2':'a1'}function opposingRear(c){return sideOf(c)==='hero'?'t2':'t1'}
function startBattle(){const ids=Object.keys(state.battle.positions).filter(id=>state.characters.some(c=>c.id===id));if(!ids.length)return toast('Поле пусто','Сначала добавьте участников.');for(const id of ids){const c=state.characters.find(x=>x.id===id);c.initiativeRoll=E.d20(c.initiative).total;c.reactionAvailable=true}state.battle.order=ids.sort((a,b)=>{const A=state.characters.find(x=>x.id===a),B=state.characters.find(x=>x.id===b);return B.initiativeRoll-A.initiativeRoll||B.initiative-A.initiative});state.battle.active=true;state.battle.round=1;state.battle.turnIndex=0;beginTurn();logBattle('Система','Бой начался. Инициатива определена.');commit('Бой начался')}
function beginTurn(){const c=currentActor();if(!c)return;state.battle.movement[c.id]=c.speed;state.battle.turnStartZones[c.id]=battlePosition(c.id);state.battle.flags[c.id]={disengaged:false,chargeReady:false,charged:false,breather:false,actionUsed:false,bonusUsed:false};c.reactionAvailable=true;c.exposedCharge=false;if(c.telegraph?.stage==='prepared')c.telegraph.stage='ready';}
function nextTurn(){if(!state.battle.active)return;if(!state.battle.order.length)return endBattle();state.battle.turnIndex++;if(state.battle.turnIndex>=state.battle.order.length){state.battle.turnIndex=0;state.battle.round++;for(const c of combatants())c.reactionAvailable=true}beginTurn();state.battle.targetId=null;commit(`Ход: ${currentActor()?.name||'—'}`)}
function endBattle(){state.battle.active=false;state.battle.order=[];state.battle.turnIndex=0;state.battle.result=null;for(const c of state.characters)c.initiativeRoll=null;commit('Бой завершён')}
function logBattle(actor,text,tone=''){state.battle.log.push({id:E.id(),time:new Date().toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'}),actor,text,tone});state.battle.log=state.battle.log.slice(-150)}
function setResult(text,hit=null){state.battle.result={id:E.id(),text,hit,time:Date.now()};setTimeout(()=>{if(state.battle.result?.text===text){state.battle.result=null;render()}},3600)}
function addCombatant(id,zone){if(state.battle.positions[id])return;state.battle.positions[id]=zone;state.battle.movement[id]=state.characters.find(c=>c.id===id)?.speed||30;if(!state.battle.order.includes(id))state.battle.order.push(id);commit('Участник выставлен')}
function removeCombatant(id){delete state.battle.positions[id];delete state.battle.movement[id];delete state.battle.flags[id];state.battle.order=state.battle.order.filter(x=>x!==id);if(state.battle.turnIndex>=state.battle.order.length)state.battle.turnIndex=0;commit('Участник снят с поля')}
function moveActor(id,direction,special=''){const c=state.characters.find(x=>x.id===id);if(!c)return;if(state.battle.active&&currentActor()?.id!==id&&!isGM())return toast('Не ваш ход');const from=battlePosition(id),idx=ZONE_ORDER.indexOf(from);if(idx<0)return;const flags=state.battle.flags[id]||(state.battle.flags[id]={});let to=ZONE_ORDER[idx+direction],cost=10;if(special==='flank'){if(!inFriendlyRear(c,from)||c.speed<40||state.battle.movement[id]!==c.speed)return toast('Фланг недоступен','Нужно начать ход в тылу, иметь скорость 40+ и не тратить движение.');to=opposingRear(c);cost=state.battle.movement[id];flags.flanked=true}else if(!to)return;
 if((state.battle.movement[id]??c.speed)<cost)return toast('Не хватает движения');if((from==='a1'||from==='a2')&&!flags.disengaged){const threatenedFrom=from==='a1'?'a2':'a1';const adjacent=state.characters.filter(x=>sideOf(x)!==sideOf(c)&&battlePosition(x.id)===threatenedFrom&&x.hp>0);for(const enemy of adjacent){if(!enemy.reactionAvailable)continue;enemy.reactionAvailable=false;const oa=enemy.actions.find(a=>a.kind==='melee'&&(a.type==='attack'||a.type==='spell'));if(oa)resolveAction(enemy,oa,c,{opportunity:true,silent:true});else logBattle(enemy.name,`может совершить провоцированную атаку по ${c.name}`, 'warn')}}
 if(c.hp<=0){logBattle(c.name,'падает во время выхода из зоны','warn');return commit(null)}state.battle.positions[id]=to;state.battle.movement[id]-=cost;if(inFriendlyRear(c,from)&&to===friendlyVanguard(c)&&state.battle.turnStartZones[id]===from)flags.chargeReady=true;else if(special!=='flank')flags.chargeReady=false;logBattle(c.name,`перемещается ${ZONES[from].code} → ${ZONES[to].code} (${cost} фт)`);commit(null)}
function directDistance(a,b){return Math.abs(ZONE_ORDER.indexOf(battlePosition(a.id))-ZONE_ORDER.indexOf(battlePosition(b.id)))*10}
function rearCover(target){const z=battlePosition(target.id);if(!inFriendlyRear(target,z))return false;return state.characters.some(c=>c.id!==target.id&&sideOf(c)===sideOf(target)&&battlePosition(c.id)===friendlyVanguard(target)&&c.hp>0)}
function legalMelee(attacker,target){const ai=ZONE_ORDER.indexOf(battlePosition(attacker.id)),ti=ZONE_ORDER.indexOf(battlePosition(target.id));return ai>=0&&ti>=0&&Math.abs(ai-ti)<=1}
function damageMultiplier(target,type){const t=String(type||'').toLowerCase();if(!t)return 1;if(target.immunities.some(x=>t.includes(x)||x.includes(t)))return 0;if(target.vulnerabilities.some(x=>t.includes(x)||x.includes(t)))return 2;if(target.resistances.some(x=>t.includes(x)||x.includes(t)))return .5;return 1}
function applyDamage(target,amount,type=''){let dmg=Math.max(0,Math.floor(Number(amount)||0)*damageMultiplier(target,type));const absorbed=Math.min(target.tempHp||0,dmg);target.tempHp-=absorbed;dmg-=absorbed;target.hp=Math.max(0,target.hp-dmg);return{applied:dmg+absorbed,mult:damageMultiplier(target,type)}}function applyHealing(target,amount){const before=target.hp;target.hp=Math.min(target.maxHp,target.hp+Math.max(0,Number(amount)||0));return target.hp-before}
function resolveAction(actor,action,target,options={}){if(!actor||!action)return;if(action.targetSide==='self')target=actor;if(!target&&action.targetSide!=='self')return toast('Выберите цель');if(action.targetSide==='enemy'&&target&&sideOf(target)===sideOf(actor))return toast('Нужна вражеская цель');if(action.targetSide==='ally'&&target&&sideOf(target)!==sideOf(actor))return toast('Нужна союзная цель');if(action.maxUses!==null&&action.currentUses<=0)return toast('Ресурс исчерпан');if(action.kind==='melee'&&target&&!legalMelee(actor,target))return toast('Цель вне досягаемости','Для ближней атаки нужно быть в той же или соседней зоне.');if(state.battle.active&&!options.opportunity&&currentActor()?.id!==actor.id&&!isGM())return toast('Не ваш ход');const flags=state.battle.flags[actor.id]||{},cost=action.cost||'action';if(!options.opportunity&&cost==='action'&&flags.actionUsed)return toast('Действие уже потрачено');if(!options.opportunity&&cost==='bonus'&&flags.bonusUsed)return toast('Бонусное действие уже потрачено');if(!options.opportunity&&cost==='reaction'&&!actor.reactionAvailable)return toast('Реакция уже потрачена');let text='',hit=null;
 try{if(action.type==='heal'){target=target||actor;const r=E.rollExpression(action.damage||'0');const healed=applyHealing(target,r.total);text=`${actor.name}: ${action.name} — ${target.name} восстанавливает ${healed} ОЗ (${r.detail})`;hit=true}else if(action.type==='save'){const mod=target.saves?.[action.saveAbility]??E.abilityMod(target.stats?.[action.saveAbility]||10);const save=E.d20(mod);const success=save.total>=(action.saveDC||10);let damage=0;if(action.damage){const r=E.rollExpression(action.damage);damage=success?(action.halfOnSave?Math.floor(r.total/2):0):r.total;damage=applyDamage(target,damage,action.damageType).applied}text=`${actor.name}: ${action.name} — ${target.name} ${success?'успех':'провал'} (${save.total} против Сл ${action.saveDC||10})${action.damage?`, ${damage} урона`:''}`;hit=!success}else if(['attack','spell'].includes(action.type)){const cover=action.kind==='ranged'&&rearCover(target),chargeAttack=flags.chargeReady&&action.kind==='melee',exposedTarget=Boolean(target?.exposedCharge),adv=chargeAttack||exposedTarget,dis=cover,mode=adv===dis?'normal':adv?'adv':'dis';const roll=E.d20(action.attackBonus||0,mode);if(exposedTarget)target.exposedCharge=false;const targetAC=target.ac+(cover?2:0);hit=roll.natural===20||(roll.natural!==1&&roll.total>=targetAC);let damage=0;if(hit&&action.damage){const r=E.rollExpression(action.damage,{crit:roll.natural===20});damage=applyDamage(target,r.total,action.damageType).applied}text=`${actor.name}: ${action.name} — ${hit?'ПОПАДАНИЕ':'ПРОМАХ'} (${roll.total} против КД ${targetAC})${hit&&action.damage?`, ${damage} урона`:''}${cover?' · укрытие тыла':''}${exposedTarget?' · уязвимость после натиска':''}`;if(chargeAttack){flags.chargeReady=false;flags.charged=true;actor.exposedCharge=true;logBattle(actor.name,'совершает натиск: первая атака с преимуществом; первая атака по нему до следующего хода тоже с преимуществом','warn')}}else if(action.damage){const r=E.rollExpression(action.damage);const damage=applyDamage(target,r.total,action.damageType).applied;text=`${actor.name}: ${action.name} — ${damage} урона (${r.detail})`;hit=true}else{text=`${actor.name} использует «${action.name}»`;hit=true}
 if(action.maxUses!==null&&!options.opportunity)action.currentUses=Math.max(0,action.currentUses-1);if(!options.opportunity&&cost==='action')flags.actionUsed=true;if(!options.opportunity&&cost==='bonus')flags.bonusUsed=true;if(!options.opportunity&&cost==='reaction')actor.reactionAvailable=false;logBattle(actor.name,text,hit?'hit':'miss');setResult(text,hit);if(!options.silent)commit(null);else setDirty()}catch(err){toast('Бросок не выполнен',err.message)}}
function disengageActor(c){if(!c)return;const flags=state.battle.flags[c.id]||(state.battle.flags[c.id]={});if(state.battle.active&&currentActor()?.id!==c.id&&!isGM())return toast('Не ваш ход');if(flags.actionUsed)return toast('Действие уже потрачено');flags.disengaged=true;flags.actionUsed=true;logBattle(c.name,'использует действие Отход');commit()}
function tacticalBreather(c){if(!c)return;if(state.battle.active&&currentActor()?.id!==c.id&&!isGM())return toast('Не ваш ход');const z=battlePosition(c.id),flags=state.battle.flags[c.id]||(state.battle.flags[c.id]={});if(!inFriendlyRear(c,z))return toast('Нужен дружественный тыл');if(state.characters.some(x=>sideOf(x)!==sideOf(c)&&battlePosition(x.id)===z&&x.hp>0))return toast('В тылу есть враг');if(flags.bonusUsed)return toast('Бонусное действие уже использовано');if(c.hitDice.current<1)return toast('Нет костей хитов');const r=E.rollExpression(`1d${c.hitDice.die}+${Math.max(0,E.abilityMod(c.stats.con))}`);const healed=applyHealing(c,r.total);c.hitDice.current--;flags.bonusUsed=true;flags.breather=true;logBattle(c.name,`тактическая передышка: +${healed} ОЗ, потрачена кость хитов`,'hit');setResult(`${c.name} восстанавливает ${healed} ОЗ`,true);commit(null)}
function investigateBoss(actor,boss,kind){const dist=directDistance(actor,boss);const magical=boss.telegraph?.nature==='magical';const dc=(magical?15:13)+Math.floor(dist/20)*2;const ability=kind==='analysis'?'int':'wis';const roll=E.d20(actor.skills?.[kind]??E.abilityMod(actor.stats[ability]));const ok=roll.total>=dc;const clue=ok?(boss.telegraph?.counter||'Контрмера не указана мастером.'):'Замысел остаётся неясным.';logBattle(actor.name,`${kind==='analysis'?'Анализ':'Восприятие'}: ${roll.total} против Сл ${dc}. ${clue}`,ok?'hit':'miss');setResult(`${actor.name}: ${clue}`,ok);commit(null)}
function actorCard(c){const current=currentActor()?.id===c.id,target=state.battle.targetId===c.id,z=battlePosition(c.id);const asset=state.assets.find(a=>a.id===c.tokenAsset);const flags=state.battle.flags[c.id]||{};return `<button class="actor ${sideOf(c)} ${current?'current':''} ${target?'target':''}" style="--actor-scale:${((c.modelScale||100)/100)*(state.settings.modelScale||1)}" data-target="${c.id}" title="${esc(c.name)}"><div class="actor-move">${state.battle.movement[c.id]??c.speed} фт</div><div class="actor-conditions">${c.conditions.slice(0,4).map(x=>`<i class="condition-icon" title="${attr(x)}">${esc(x[0].toUpperCase())}</i>`).join('')}${c.telegraph?.stage&&c.telegraph.stage!=='done'?`<i class="telegraph-mark" title="${attr(c.telegraph.name)}">!</i>`:''}</div>${asset?.data?`<img src="${attr(asset.data)}" alt="">`:`<div class="actor-placeholder">${esc(initials(c.name))}</div>`}<div class="actor-plate"><b>${esc(c.name)}</b><span class="actor-hp"><i style="width:${pct(c.hp,c.maxHp)}%"></i></span><small>${c.hp}/${c.maxHp}${flags.chargeReady?' · НАТИСК':''}</small></div></button>`}
function renderBattle(){const actors=state.characters.filter(c=>battlePosition(c.id));const active=currentActor();const canAct=active&&(isGM()||active.id===state.session.characterId);const actions=isGM()?`<button class="outline-btn" data-action="battle-setup">Расстановка</button>${state.battle.active?'<button class="danger-btn" data-action="end-battle">Завершить</button>':'<button class="red-btn" data-action="start-battle">Начать бой</button>'}`:'';return `<section class="view">${heading('ТАКТИЧЕСКАЯ ЛИНИЯ · 40 ФУТОВ','Поле боя','Четыре зоны по 10 футов. Т1 → А1 → А2 → Т2. Все результаты атак видит общий стол.',actions)}<div class="battle-shell"><div class="battle-main"><div class="battle-bar"><div class="round-seal"><b>${state.battle.round}</b></div><div class="battle-status"><small>${state.battle.active?'ТЕКУЩИЙ ХОД':'ПОДГОТОВКА'}</small><b>${esc(active?.name||'Бой не начат')}</b></div><div class="initiative-track">${state.battle.order.map((id,i)=>{const c=state.characters.find(x=>x.id===id);return c?`<button class="init-chip ${i===state.battle.turnIndex&&state.battle.active?'current':''}" data-target="${c.id}">${esc(initials(c.name))}<small>${c.initiativeRoll??'—'}</small></button>`:''}).join('')}</div>${state.battle.active&&canAct?'<button class="primary" data-action="next-turn">Закончить ход →</button>':''}</div><div class="battlefield-wrap"><div class="battlefield ${battleScene()?.backgroundAsset?'has-background':''}">${battleBackground()}<div class="battle-vignette"></div><div class="zones">${ZONE_ORDER.map((key,i)=>`<section class="battle-zone ${ZONES[key].side}"><header class="zone-head"><span class="zone-code">${ZONES[key].code}</span><div><b>${ZONES[key].name}</b><small>${i*10}–${(i+1)*10} футов</small></div></header><div class="zone-actors">${actors.filter(c=>battlePosition(c.id)===key).map(actorCard).join('')}</div></section>`).join('')}</div>${state.battle.result?`<div class="result-banner ${state.battle.result.hit===true?'hit':state.battle.result.hit===false?'miss':''}">${esc(state.battle.result.hit===true?'ПОПАДАНИЕ':state.battle.result.hit===false?'ПРОМАХ':'РЕЗУЛЬТАТ')}<small>${esc(state.battle.result.text)}</small></div>`:''}</div></div></div><aside class="context-panel">${renderBattleContext(active)}</aside></div></section>`}
function battleScene(){return state.scenes.find(x=>x.id===state.battle.sceneId)||null}function battleBackground(){const s=battleScene(),a=state.assets.find(x=>x.id===s?.backgroundAsset);return a?.data?`<img class="battle-bg" src="${attr(a.data)}" alt="фон сцены">`:''}
function renderBattleContext(active){const target=state.characters.find(c=>c.id===state.battle.targetId);const editable=active&&(isGM()||active.id===state.session.characterId);const tabs=`<div class="context-tabs"><button data-context="actions" class="${contextTab==='actions'?'active':''}">Действия</button><button data-context="move" class="${contextTab==='move'?'active':''}">Движение</button><button data-context="rolls" class="${contextTab==='rolls'?'active':''}">Броски</button><button data-context="log" class="${contextTab==='log'?'active':''}">Журнал</button></div>`;let body='';if(!active)body=empty('⚔','Ожидание боя','Мастер добавляет участников через «Расстановка» и начинает инициативу.');else if(contextTab==='actions'){body=`<div class="inspector"><span class="section-kicker">АКТИВНЫЙ</span><h2>${esc(active.name)}</h2><p>Цель: <b>${esc(target?.name||'не выбрана')}</b></p></div><div class="action-list">${active.actions.map(a=>`<button class="action-button" ${editable?'':'disabled'} data-combat-action="${a.id}" data-actor="${active.id}"><b>${esc(a.name)}</b><small>${esc(E.actionDetail(a))}</small></button>`).join('')||'<p class="micro">У персонажа нет действий.</p>'}</div>${active.role==='enemy'&&active.boss&&isGM()?'<button class="outline-btn" data-action="boss-telegraph" data-id="'+active.id+'">Подготовить действие босса</button>':''}${target?.telegraph?.stage&&target.telegraph.stage!=='done'&&sideOf(target)!==sideOf(active)?`<div class="help-callout">Босс готовит: <b>${esc(target.telegraph.name)}</b><div class="editor-button-row"><button class="small" data-investigate="perception" data-actor="${active.id}" data-boss="${target.id}">Восприятие</button><button class="small" data-investigate="analysis" data-actor="${active.id}" data-boss="${target.id}">Анализ</button></div></div>`:''}` }else if(contextTab==='move'){const z=battlePosition(active.id),idx=ZONE_ORDER.indexOf(z),flags=state.battle.flags[active.id]||{};body=`<div class="move-controls"><b>${ZONES[z]?.code||'—'} · осталось ${state.battle.movement[active.id]??active.speed} фт</b><button class="outline-btn" data-move="-1" data-id="${active.id}" ${!editable||idx<=0?'disabled':''}>← 10 футов</button><button class="outline-btn" data-move="1" data-id="${active.id}" ${!editable||idx>=3?'disabled':''}>10 футов →</button><button class="small" data-action="disengage" data-id="${active.id}" ${!editable||flags.disengaged?'disabled':''}>Отход: действие</button><button class="small" data-action="flank" data-id="${active.id}" ${!editable?'disabled':''}>Фланг: всё движение</button><button class="small" data-action="breather" data-id="${active.id}" ${!editable?'disabled':''}>Передышка: бонусное</button></div><div class="help-callout">Выход из авангарда без Отхода провоцирует реакции врагов в соседнем авангарде. Переход из тыла в авангард подготавливает Натиск.</div>`}else if(contextTab==='rolls'){body=`<div class="dice-row">${[4,6,8,10,12,20,100].map(d=>`<button class="die-btn" data-die="${d}">к${d}</button>`).join('')}</div><div class="custom-roll"><input class="text-input" id="customRoll" value="1d20"><button class="primary" data-action="custom-roll">Бросить</button></div>`}else body=`<div class="log-list">${[...state.battle.log].reverse().map(x=>`<div class="log-entry ${x.tone||''}"><small>${esc(x.time)} · ${esc(x.actor)}</small><p>${esc(x.text)}</p></div>`).join('')||'<p class="micro">Журнал боя пуст.</p>'}</div>`;return tabs+body}
function openBattleSetup(){const available=state.characters.filter(c=>!battlePosition(c.id));modal('Расстановка','До двух моделей читаются раздельно; большее число поддерживается, но клетка становится плотнее.',`<div class="form-grid">${selectField('Участник','bsChar',available.map(c=>[c.id,`${c.name} · ${c.role==='enemy'?'враг':'герой'}`]),available[0]?.id||'')}${selectField('Начальная зона','bsZone',ZONE_ORDER.map(z=>[z,`${ZONES[z].code} · ${ZONES[z].name}`]),'t1')}</div><div class="member-list">${Object.entries(state.battle.positions).map(([id,z])=>{const c=state.characters.find(x=>x.id===id);return c?`<span>${esc(c.name)} · ${ZONES[z].code} <button class="small" data-remove-combatant="${c.id}">Снять</button></span>`:''}).join('')||'<span>Поле пусто</span>'}</div>`,`<button class="dark-btn" data-close>Закрыть</button><button class="primary" data-modal-submit ${available.length?'':'disabled'}>Выставить</button>`,false,()=>{const id=$('#bsChar').value,z=$('#bsZone').value;if(id)addCombatant(id,z);closeModal();openBattleSetup()})}
function renderJournal(){const own=ownCharacter(),personal=state.journal.personal[state.session.characterId]||'';return `<section class="view">${heading('ЗАМЕТКИ И ХРОНИКА','Журнал','Личные записи принадлежат игроку; партийный журнал и опубликованная хроника видны по разрешениям.',isGM()?'<button class="red-btn" data-action="chronicle-add">＋ Запись хроники</button>':'')}<div class="journal-layout"><section class="journal-paper"><span class="section-kicker">${isGM()?'ПАРТИЙНЫЙ ЖУРНАЛ':'ЛИЧНЫЕ ЗАПИСИ'}</span><h2>${isGM()?'Общие заметки':esc(own?.name||'Мой журнал')}</h2><textarea class="text-area" id="journalText" placeholder="Пишите здесь…">${esc(isGM()?state.journal.party:personal)}</textarea><button class="primary" data-action="save-journal">Сохранить заметки</button></section><aside class="panel"><div class="panel-head"><h2>Хроника</h2><small>ОПУБЛИКОВАНО</small></div><div class="chronicle-list">${state.journal.chronicle.length?[...state.journal.chronicle].reverse().map(x=>`<article class="chronicle-entry"><small>${esc(new Date(x.date).toLocaleDateString('ru'))}</small><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>${isGM()?`<button class="small" data-delete-chronicle="${x.id}">Удалить</button>`:''}</article>`).join(''):'<p class="micro">Хроника пока не начата.</p>'}</div></aside></div></section>`}
function openChronicle(){modal('Новая запись хроники','Опубликованную запись увидят все участники.',`${formField('Заголовок','chTitle','Новая глава')}<label class="form-field"><span>Текст</span><textarea class="text-area" id="chText"></textarea></label>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Опубликовать</button>`,false,()=>{state.journal.chronicle.push({id:E.id(),date:now(),title:$('#chTitle').value.trim()||'Без названия',text:$('#chText').value});closeModal();commit('Хроника дополнена')})}
function renderWorld(){const map=state.world.maps.find(x=>x.id===selectedMap)||state.world.maps[0];return `<section class="view">${heading('СЕВЕРНЫЙ МИР','Карта и маршруты','Канонический северный атлас служит основой, но названия, описания и дорожные записи редактируются мастером.',isGM()?'<button class="red-btn" data-action="new-route">＋ Маршрут</button>':'')}<div class="map-layout"><div class="map-panel"><div class="map-toolbar">${state.world.maps.map(m=>`<button class="${m.id===map.id?'active':''}" data-map="${m.id}">${esc(m.name)}</button>`).join('')}</div><div class="map-viewport"><img class="map-image" src="${attr(map.src)}" alt="${attr(map.name)}"></div><div class="map-credit"><b>${esc(map.name)}</b><span>${esc(map.desc)}</span></div></div><aside class="world-side"><section class="panel"><div class="panel-head"><h2>Маршруты</h2><small>${state.world.routes.length}</small></div><div class="route-list">${state.world.routes.length?state.world.routes.map(r=>`<article class="route-card"><small>${esc(r.from)} → ${esc(r.to)}</small><h3>${esc(r.name)}</h3><p>${esc(r.distance||'Расстояние не задано')} · ${esc(r.danger||'опасность не задана')}</p>${isGM()?`<button class="small" data-edit-route="${r.id}">Изменить</button><button class="small" data-delete-route="${r.id}">Удалить</button>`:''}</article>`).join(''):'<p class="micro">Маршрутов пока нет.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Места</h2><small>СЕВЕР</small></div><div class="lore-list">${state.world.locations.filter(x=>isGM()||x.discovered).map(x=>`<article class="lore-card"><h3>${esc(x.name)}</h3><p>${esc(x.description||'Описание оставлено для вашей кампании.')}</p>${isGM()?`<button class="small" data-edit-location="${x.id}">Изменить</button>`:''}</article>`).join('')}</div></section></aside></div></section>`}
function openRoute(id=null){const existing=state.world.routes.find(x=>x.id===id),route=existing?clone(existing):{id:E.id(),name:'Северная дорога',from:state.world.locations[0]?.name||'',to:state.world.locations[1]?.name||'',distance:'',danger:'',notes:'',available:true};modal(existing?'Изменить маршрут':'Новый маршрут','Маршрут — редактируемая запись кампании, а не автоматическое путешествие.',`<div class="form-grid">${formField('Название','rtName',route.name)}${formField('Откуда','rtFrom',route.from)}${formField('Куда','rtTo',route.to)}${formField('Расстояние / время','rtDistance',route.distance||'')}${formField('Опасность','rtDanger',route.danger||'')}<label class="form-field"><span><input id="rtAvailable" type="checkbox" ${route.available!==false?'checked':''}> виден игрокам</span></label></div><label class="form-field"><span>Заметки</span><textarea class="text-area" id="rtNotes">${esc(route.notes||'')}</textarea></label>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>${existing?'Сохранить':'Создать'}</button>`,false,()=>{Object.assign(route,{name:$('#rtName').value.trim()||'Маршрут',from:$('#rtFrom').value.trim(),to:$('#rtTo').value.trim(),distance:$('#rtDistance').value,danger:$('#rtDanger').value,notes:$('#rtNotes').value,available:$('#rtAvailable').checked});if(existing)Object.assign(existing,route);else state.world.routes.push(route);closeModal();commit(existing?'Маршрут обновлён':'Маршрут создан')})}
function editLocation(id){const x=state.world.locations.find(v=>v.id===id);if(!x)return;modal('Место на карте','Терминология Севера редактируема для вашей версии мира.',`${formField('Название','loName',x.name)}<label class="form-field"><span>Описание игрокам</span><textarea class="text-area" id="loDesc">${esc(x.description)}</textarea></label><label class="form-field"><span>Заметки мастера</span><textarea class="text-area" id="loGm">${esc(x.gmNotes)}</textarea></label><label class="form-field"><span><input type="checkbox" id="loFound" ${x.discovered?'checked':''}> открыто игрокам</span></label>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Сохранить</button>`,false,()=>{x.name=$('#loName').value.trim()||x.name;x.description=$('#loDesc').value;x.gmNotes=$('#loGm').value;x.discovered=$('#loFound').checked;closeModal();commit('Место обновлено')})}

function renderCities(){return `<section class="view">${heading('ГОРОДА И ТОРГОВЛЯ','Поселения и торговцы','Игроки покупают и продают доступные товары. Только мастер создаёт города, продавцов, цены и остатки.',isGM()?'<button class="red-btn" data-action="new-city">＋ Создать город</button>':'')} ${state.cities.length?`<div class="city-grid">${state.cities.filter(c=>isGM()||c.available).map(c=>`<article class="city-card"><span class="section-kicker">${c.available?'ДОСТУПЕН':'СКРЫТ'}</span><h2>${esc(c.name)}</h2><p>${esc(c.description||'Описание города не заполнено.')}</p><div class="merchant-list">${c.merchants.filter(m=>isGM()||m.available).map(m=>`<div class="merchant"><div class="merchant-head"><div><b>${esc(m.name)}</b><small>${esc(m.type||'торговец')}</small></div>${isGM()?`<div><button class="small" data-edit-merchant="${c.id}:${m.id}">Изм.</button><button class="small" data-new-stock="${c.id}:${m.id}">＋ товар</button><button class="small" data-delete-merchant="${c.id}:${m.id}">×</button></div>`:''}</div><div class="stock-table">${m.stock.filter(i=>isGM()||i.available).map(i=>`<div class="inventory-row"><div><b>${esc(i.name)}</b><small>${i.quantity} шт. · ${i.price} зм</small></div><div>${!isGM()?`<button class="small" data-buy="${c.id}:${m.id}:${i.id}">Купить</button>`:''}${isGM()?`<button class="small" data-edit-stock="${c.id}:${m.id}:${i.id}">Изм.</button><button class="small" data-delete-stock="${c.id}:${m.id}:${i.id}">×</button>`:''}</div></div>`).join('')||'<p class="micro">Прилавок пуст.</p>'}</div>${!isGM()&&ownCharacter()?.inventory.length?`<div class="merchant-head"><small>ПРОДАТЬ · ${Math.round((m.buyRate??.5)*100)}% СТОИМОСТИ</small></div><div class="inventory-list">${ownCharacter().inventory.map(i=>`<div class="inventory-row"><span>${esc(i.name)} · ${i.quantity||1} шт.</span><button class="small" data-sell="${c.id}:${m.id}:${i.id}">Продать 1</button></div>`).join('')}</div>`:''}</div>`).join('')||'<p class="micro">Торговцев пока нет.</p>'}</div>${isGM()?`<div class="heading-actions"><button class="small" data-edit-city="${c.id}">Изменить город</button><button class="small" data-new-merchant="${c.id}">＋ торговец</button><button class="danger-btn small" data-delete-city="${c.id}">Удалить город</button></div>`:''}</article>`).join('')}</div>`:empty('♜','Города ещё не созданы',isGM()?'Создайте поселение, добавьте торговцев и вручную наполните их прилавки.':'Мастер ещё не открыл города для торговли.',isGM()?'<button class="red-btn" data-action="new-city">Создать город</button>':'')}</section>`}
function openCity(id=null){const existing=state.cities.find(x=>x.id===id),city=existing?clone(existing):{id:E.id(),name:'Новый город',description:'',available:true,merchants:[]};modal(existing?'Изменить город':'Новый город',existing?'Название, описание и доступность можно менять в любой момент.':'Город начинается пустым: без навязанных торговцев и товаров.',`<div class="form-grid">${formField('Название','ciName',city.name)}<label class="form-field"><span><input id="ciAvailable" type="checkbox" ${city.available!==false?'checked':''}> доступен игрокам</span></label></div><label class="form-field"><span>Описание</span><textarea id="ciDesc" class="text-area">${esc(city.description||'')}</textarea></label>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>${existing?'Сохранить':'Создать'}</button>`,false,()=>{city.name=$('#ciName').value.trim()||'Новый город';city.description=$('#ciDesc').value;city.available=$('#ciAvailable').checked;if(existing)Object.assign(existing,city);else state.cities.push(city);closeModal();commit(existing?'Город обновлён':'Город создан')})}
function openMerchant(cityId){const city=state.cities.find(x=>x.id===cityId);if(!city)return;modal('Новый торговец',city.name,`<div class="form-grid">${formField('Имя','meName','Торговец')}${formField('Специализация','meType','Общие товары')}</div>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Добавить</button>`,false,()=>{city.merchants.push({id:E.id(),name:$('#meName').value.trim()||'Торговец',type:$('#meType').value,available:true,buyRate:.5,stock:[]});closeModal();commit('Торговец добавлен')})}
function editMerchant(spec){const {merchant}=findMerchant(spec);if(!merchant)return;modal('Настройки торговца',merchant.name,`<div class="form-grid">${formField('Имя','emName',merchant.name)}${formField('Специализация','emType',merchant.type)}${formField('Выкуп, % стоимости','emRate',Math.round((merchant.buyRate??.5)*100),'number','min="0" max="100"')}<label class="form-field"><span><input id="emAvailable" type="checkbox" ${merchant.available?'checked':''}> доступен игрокам</span></label></div>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Сохранить</button>`,false,()=>{merchant.name=$('#emName').value.trim()||merchant.name;merchant.type=$('#emType').value;merchant.buyRate=E.clamp($('#emRate').value,0,100)/100;merchant.available=$('#emAvailable').checked;closeModal();commit('Торговец обновлён')})}
function findMerchant(spec){const[cid,mid]=spec.split(':');const city=state.cities.find(x=>x.id===cid);return{city,merchant:city?.merchants.find(x=>x.id===mid)}}
function openStock(spec){const {merchant}=findMerchant(spec);if(!merchant)return;const iid=spec.split(':')[2],existing=merchant.stock.find(x=>x.id===iid),item=existing?clone(existing):{id:E.id(),name:'Новый предмет',price:1,quantity:1,weight:0,description:'',available:true};modal(existing?'Изменить товар':'Товар на прилавке',merchant.name,`<div class="form-grid">${formField('Название','stName',item.name)}${formField('Цена, зм','stPrice',item.price,'number','min="0" step="0.01"')}${formField('Количество','stQty',item.quantity,'number','min="0" step="1"')}${formField('Вес','stWeight',item.weight||0,'number','min="0" step="0.1"')}<label class="form-field"><span><input id="stAvailable" type="checkbox" ${item.available!==false?'checked':''}> доступен игрокам</span></label></div><label class="form-field"><span>Описание</span><textarea class="text-area" id="stDesc">${esc(item.description||'')}</textarea></label>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>${existing?'Сохранить':'Добавить'}</button>`,false,()=>{Object.assign(item,{name:$('#stName').value.trim()||'Предмет',price:Math.max(0,Number($('#stPrice').value)||0),quantity:Math.max(0,Math.floor(Number($('#stQty').value)||0)),weight:Math.max(0,Number($('#stWeight').value)||0),description:$('#stDesc').value,available:$('#stAvailable').checked});if(existing)Object.assign(existing,item);else merchant.stock.push(item);closeModal();commit(existing?'Товар обновлён':'Товар добавлен')})}
function buyItem(spec){const[cid,mid,iid]=spec.split(':'),city=state.cities.find(x=>x.id===cid),m=city?.merchants.find(x=>x.id===mid),item=m?.stock.find(x=>x.id===iid),hero=ownCharacter();if(!item||!hero||item.quantity<1)return toast('Покупка невозможна');if(hero.currency.gp<item.price)return toast('Недостаточно золота',`Нужно ${item.price} зм.`);hero.currency.gp-=item.price;item.quantity--;const owned=hero.inventory.find(x=>x.name===item.name);if(owned)owned.quantity++;else hero.inventory.push({id:E.id(),name:item.name,quantity:1,weight:item.weight,description:item.description,value:item.price});commit(`${item.name} куплен за ${item.price} зм`)}

function sellItem(spec){const[cid,mid,iid]=spec.split(':'),city=state.cities.find(x=>x.id===cid),m=city?.merchants.find(x=>x.id===mid),hero=ownCharacter(),item=hero?.inventory.find(x=>x.id===iid);if(!m||!item||item.quantity<1)return toast('Продажа невозможна');const price=Math.max(0,Math.round(Number(item.value||0)*(m.buyRate??.5)*100)/100);hero.currency.gp=Math.round((hero.currency.gp+price)*100)/100;item.quantity--;let stock=m.stock.find(x=>x.name===item.name);if(stock)stock.quantity++;else m.stock.push({id:E.id(),name:item.name,price:Number(item.value||0),quantity:1,weight:item.weight||0,description:item.description||'',available:true});if(item.quantity<=0){hero.inventory=hero.inventory.filter(x=>x.id!==item.id);for(const slot of Object.keys(hero.equipment))if(hero.equipment[slot]===item.id)hero.equipment[slot]=null}commit(`${item.name} продан за ${price} зм`)}
function assetById(id){return state.assets.find(x=>x.id===id)}function renderScenes(){if(!selectedSceneId||!state.scenes.some(x=>x.id===selectedSceneId))selectedSceneId=state.scenes[0]?.id||null;const scene=state.scenes.find(x=>x.id===selectedSceneId);const actions=isGM()?'<button class="red-btn" data-action="new-scene">＋ Новая сцена</button>':'';return `<section class="view">${heading('КОНСТРУКТОР СЦЕН','Сцены','Мастер выбирает фон и размещает импортированные объекты. Каждый элемент перемещается и масштабируется относительно сцены.',actions)}${scene?`<div class="scene-layout"><div class="scene-stage" id="sceneStage" style="min-height:0;aspect-ratio:${Math.max(1,Number(scene.width)||1600)}/${Math.max(1,Number(scene.height)||900)};${sceneBackgroundStyle(scene)}">${scene.objects.map(o=>sceneObject(o)).join('')}</div><aside class="panel"><div class="panel-head"><h2>${esc(scene.name)}</h2><small>${scene.width} × ${scene.height}</small></div><div class="inspector">${isGM()?`<label class="form-field"><span>Активная сцена боя</span><input type="checkbox" data-scene-battle="${scene.id}" ${state.battle.sceneId===scene.id?'checked':''}></label><label class="form-field"><span>Фон</span><select class="select" data-scene-bg="${scene.id}"><option value="">Без фона</option>${state.assets.filter(a=>a.kind==='image').map(a=>`<option value="${a.id}" ${a.id===scene.backgroundAsset?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label class="form-field"><span>Добавить объект</span><select class="select" id="sceneAsset"><option value="">Выберите изображение или модель</option>${state.assets.filter(a=>a.kind==='image'||a.kind==='model').map(a=>`<option value="${a.id}">${esc(a.name)} · ${a.kind==='model'?'3D':'PNG'}</option>`).join('')}</select></label><button class="primary" data-action="add-scene-object" data-id="${scene.id}">Разместить</button><p class="micro">Перетаскивайте объекты мышью. Колесо меняет относительный масштаб. Кнопка × удаляет объект.</p><button class="small" data-edit-scene="${scene.id}">Название и размер</button><button class="danger-btn" data-delete-scene="${scene.id}">Удалить сцену</button>`:'<p class="micro">Сцена управляется мастером.</p>'}</div><div class="scene-list">${state.scenes.map(s=>`<button class="action-button ${s.id===scene.id?'active-card':''}" data-scene="${s.id}"><b>${esc(s.name)}</b><small>${s.objects.length} объектов</small></button>`).join('')}</div></aside></div>`:empty('▧','Сцен пока нет',isGM()?'Создайте сцену, затем назначьте фон и объекты из медиатеки.':'Мастер ещё не открыл сцену.',isGM()?'<button class="red-btn" data-action="new-scene">Создать сцену</button>':'')}</section>`}
function sceneBackgroundStyle(s){const a=assetById(s.backgroundAsset);return a?.data?`background-image:url('${attr(a.data)}');background-size:cover;background-position:center`:''}
function sceneObject(o){const a=assetById(o.assetId);if(!a)return'';const visual=a.kind==='model'?`<div class="model-viewport" data-model-asset="${a.id}" aria-label="3D-модель ${attr(a.name)}"><span>Загрузка 3D…</span></div>`:`<img src="${attr(a.data)}" alt="${attr(a.name)}">`;return `<div class="scene-object ${a.kind==='model'?'is-model':''}" data-object="${o.id}" style="left:${o.x}%;top:${o.y}%;width:${o.scale}%">${visual}${isGM()?`<button data-delete-object="${o.id}">×</button>`:''}</div>`}
function modelRuntime(){return modelRuntimePromise||(modelRuntimePromise=Promise.all([import('/vendor/three.module.min.js'),import('/vendor/loaders/GLTFLoader.js')]).then(([THREE,loader])=>({THREE,GLTFLoader:loader.GLTFLoader})))}
async function mountSceneModels(){const nodes=$$('[data-model-asset]');if(!nodes.length)return;let runtime;try{runtime=await modelRuntime()}catch(error){for(const node of nodes)node.innerHTML=`<span>3D недоступно<br>${esc(error.message)}</span>`;return}for(const node of nodes){if(node.dataset.modelReady)return;node.dataset.modelReady='loading';const asset=assetById(node.dataset.modelAsset);if(!asset?.data)continue;try{const {THREE,GLTFLoader}=runtime,response=await fetch(asset.data),buffer=await response.arrayBuffer(),renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'high-performance'}),scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(32,1,.01,10000);renderer.setPixelRatio(Math.min(globalThis.devicePixelRatio||1,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;scene.add(new THREE.HemisphereLight(0xdcecff,0x182027,2.1));const key=new THREE.DirectionalLight(0xffe0bc,3.2);key.position.set(3,5,4);scene.add(key);const fill=new THREE.DirectionalLight(0x8ab7d1,1.2);fill.position.set(-4,2,-3);scene.add(fill);const loader=new GLTFLoader();loader.parse(buffer,'',gltf=>{if(node.isConnected===false){renderer.dispose();return}const model=gltf.scene;scene.add(model);model.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),span=Math.max(size.x,size.y,size.z,1);model.position.sub(center);const baseY=model.position.y;camera.near=Math.max(span/1000,.01);camera.far=span*100;camera.position.set(span*.78,span*.3,span*1.9);camera.lookAt(0,0,0);camera.updateProjectionMatrix();const mixer=gltf.animations?.length?new THREE.AnimationMixer(model):null;if(mixer)mixer.clipAction(gltf.animations[0]).play();let previous=performance.now(),frame=0,observer=null;const resize=()=>{const width=Math.max(node.clientWidth||220,80),height=Math.max(node.clientHeight||260,100);renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix()};node.replaceChildren(renderer.domElement);node.dataset.modelReady='yes';resize();if(globalThis.ResizeObserver){observer=new ResizeObserver(resize);observer.observe(node)}const stop=()=>{cancelAnimationFrame(frame);observer?.disconnect();model.traverse(object=>{object.geometry?.dispose?.();const materials=Array.isArray(object.material)?object.material:[object.material];for(const material of materials)if(material){for(const value of Object.values(material))if(value?.isTexture)value.dispose();material.dispose?.()}});renderer.dispose()};const animate=time=>{if(node.isConnected===false){stop();return}const delta=Math.min((time-previous)/1000,.1);previous=time;if(mixer)mixer.update(delta);model.rotation.y=Math.sin(time/4200)*.075;model.position.y=baseY+Math.sin(time/1100)*span*.008;renderer.render(scene,camera);frame=requestAnimationFrame(animate)};frame=requestAnimationFrame(animate)},error=>{renderer.dispose();node.innerHTML=`<span>Модель не открыта<br>${esc(error.message||error)}</span>`})}catch(error){node.innerHTML=`<span>Модель не открыта<br>${esc(error.message)}</span>`}}}
function openScene(id=null){const existing=state.scenes.find(x=>x.id===id),scene=existing?clone(existing):{id:E.id(),name:'Новая сцена',width:1600,height:900,backgroundAsset:null,objects:[]};modal(existing?'Параметры сцены':'Новая сцена','Размер определяет пропорции рабочего кадра; элементы хранятся в процентах и остаются относительными.',`<div class="form-grid">${formField('Название','scName',scene.name)}${formField('Ширина','scWidth',scene.width,'number','min="320" max="8192"')}${formField('Высота','scHeight',scene.height,'number','min="240" max="8192"')}</div>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>${existing?'Сохранить':'Создать'}</button>`,false,()=>{scene.name=$('#scName').value.trim()||'Новая сцена';scene.width=E.clamp($('#scWidth').value,320,8192);scene.height=E.clamp($('#scHeight').value,240,8192);if(existing)Object.assign(existing,scene);else state.scenes.push(scene);selectedSceneId=scene.id;closeModal();commit(existing?'Сцена обновлена':'Сцена создана')})}
function renderLibrary(){const visible=mediaTab==='all'?state.assets:state.assets.filter(a=>a.kind===mediaTab);const actions=canEditMedia()?'<button class="red-btn" data-action="upload-assets">＋ Импорт файлов</button>':'';return `<section class="view">${heading('ОБЩИЕ МАТЕРИАЛЫ','Медиатека','Полноразмерные PNG, изображения, модели, музыка, звуки и пакеты. Редактирование доступно мастеру и назначенным редакторам.',actions)}<div class="media-tabs">${[['all','Все'],['image','Изображения'],['audio','Звук'],['model','Модели'],['spell','Заклинания'],['mod','Моды']].map(([v,t])=>`<button data-media-tab="${v}" class="${mediaTab===v?'active':''}">${t}</button>`).join('')}</div>${visible.length?`<div class="media-grid">${visible.map(a=>`<article class="media-card"><div class="media-preview">${a.kind==='image'?`<img src="${attr(a.data)}" alt="">`:a.kind==='audio'?'<span>♪</span>':a.kind==='model'?'<span>♟</span>':'<span>◇</span>'}</div><b>${esc(a.name)}</b><small>${esc(a.kind)} · ${formatBytes(a.size)}</small><div class="media-actions">${a.kind==='audio'?`<button class="small" data-play-asset="${a.id}">Воспроизвести</button>`:''}${canEditMedia()?`<button class="small" data-delete-asset="${a.id}">Удалить</button>`:''}</div></article>`).join('')}</div>`:empty('♪','Медиатека пуста',canEditMedia()?'Импортируйте собственные материалы. Кампания не содержит навязанных героев, врагов или сцен.':'Мастер ещё не добавил доступные материалы.',canEditMedia()?'<button class="red-btn" data-action="upload-assets">Импортировать</button>':'')}<input type="file" id="assetInput" multiple hidden accept="image/png,image/jpeg,image/webp,image/gif,audio/*,.glb,.gltf,.json,.zip"></section>`}
function formatBytes(n=0){if(n<1024)return`${n} Б`;if(n<1048576)return`${(n/1024).toFixed(1)} КБ`;return`${(n/1048576).toFixed(1)} МБ`}function kindForFile(f){if(f.type.startsWith('image/'))return'image';if(f.type.startsWith('audio/'))return'audio';if(/\.(glb|gltf)$/i.test(f.name))return'model';if(/spell/i.test(f.name))return'spell';return'mod'}
async function importAssets(files){if(!canEditMedia())return toast('Нет права редактировать медиатеку');for(const f of files){if(f.size>8*1024*1024){toast('Файл слишком велик для встроенного хранилища',`${f.name}: максимум 8 МБ`);continue}const data=await new Promise((res,rej)=>{const r=new FileReader;r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)});state.assets.push({id:E.id(),name:f.name,kind:kindForFile(f),mime:f.type,size:f.size,data,createdAt:now(),createdBy:state.session.clientId})}commit(`Добавлено файлов: ${files.length}`)}
function renderPhoto(){if(!canEditMedia())return `<section class="denied-panel">${empty('◩','Фоторедактор закрыт','Мастер может выдать вам право редактирования медиатеки.')}</section>`;return window.DragonSagaImageEditor?.renderMarkup?.()||empty('◩','Редактор недоступен','Модуль редактора не загрузился.')}
function renderWorkshop(){if(!isGM())return `<section class="denied-panel">${empty('⚒','Только для мастера','Конструктор и права кампании доступны владельцу комнаты.')}</section>`;const list=state.content[workshopTab]||[];return `<section class="view">${heading('МАСТЕРСКАЯ','Конструктор кампании','Создавайте контент с нуля: существа, предметы, действия и декларативные мод-пакеты без исполняемого кода. Здесь нет демонстрационного ростера или готовых столкновений.','<button class="outline-btn" data-action="import-mod">Импорт мода</button><button class="outline-btn" data-action="export-mod">Экспорт мода</button><button class="red-btn" data-action="workshop-add">＋ Создать</button>')}<div class="workshop-tabs">${[['creatures','Существа'],['items','Предметы'],['actions','Действия'],['mods','Моды']].map(([v,t])=>`<button data-workshop-tab="${v}" class="${workshopTab===v?'active':''}">${t}</button>`).join('')}</div>${list.length?`<div class="content-grid">${list.map(x=>`<article class="content-card"><span class="section-kicker">${esc(workshopTab)}</span><h3>${esc(x.name)}</h3><p class="micro">${esc(x.description||'Описание не заполнено')}</p><button class="small" data-delete-content="${workshopTab}:${x.id}">Удалить</button></article>`).join('')}</div>`:empty('⚒','Раздел пуст','Добавьте только тот контент, который нужен вашей кампании.','<button class="outline-btn" data-action="workshop-add">Создать запись</button>')}<input id="modInput" type="file" accept="application/json,.json" hidden></section>`}
function openWorkshopItem(){const labels={creatures:'существо',items:'предмет',actions:'действие',mods:'мод'};modal(`Новое ${labels[workshopTab]||'содержимое'}`,'Запись можно использовать как библиотечную основу; она не появляется в кампании автоматически.',`${formField('Название','woName','Новая запись')}<label class="form-field"><span>Описание / правила</span><textarea class="text-area" id="woDesc"></textarea></label>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Создать</button>`,false,()=>{state.content[workshopTab].push({id:E.id(),name:$('#woName').value.trim()||'Новая запись',description:$('#woDesc').value,createdAt:now()});closeModal();commit('Запись создана')})}
function renderRules(){const common=[['Линия из четырёх зон','Т1 — тыл героев, А1 — авангард героев, А2 — авангард врагов, Т2 — тыл врагов. Каждая соседняя зона находится в 10 футах.'],['Движение и реакции','Шаг в соседнюю зону стоит 10 футов. Выход из авангарда без действия «Отход» вызывает провоцированные атаки всех врагов в соседнем авангарде, если их реакция доступна.'],['Фланг','Существо, начавшее ход в своём тылу и имеющее скорость 40 футов или выше, может потратить всё движение и перейти во вражеский тыл без провоцированных атак.'],['Натиск','Начните в тылу, перейдите в свой авангард и совершите ближнюю атаку. Первая атака получает преимущество; первая атака по совершившему натиск до его следующего хода тоже получает преимущество.'],['Тактическая передышка','В дружественном тылу без врагов можно потратить бонусное действие и одну Кость Хитов, чтобы восстановить ОЗ.'],['Укрытие тыла','Если союзник занимает дружественный авангард, существа в тылу получают +2 к КД и помеху для входящих прямых дальнобойных атак.'],['Подготовка босса','Босс пропускает или заряжает ход и открыто показывает особое действие. Восприятие или Анализ раскрывают контрмеру; Сл зависит от природы действия и расстояния. Проверка не запрещает прочие действия.']];const role=isGM()?[['Полномочия мастера','Мастер создаёт содержимое, редактирует мир, города и медиатеку, назначает героев, начинает бой и может исправить любое состояние комнаты.'],['Пустая кампания','Новый стол не содержит демонстрационных героев, врагов, сцен, атак, предметов или магазинов. Импорт всегда сохраняет исходный текст.'],['Сетевая власть','Сервер фильтрует скрытые данные и проверяет изменения игроков. Для интернета используйте HTTPS/reverse proxy; для LAN или Hamachi передайте адрес и код комнаты.']]:[['Свобода игрока','Вы редактируете назначенного героя, снаряжение и личный журнал и выполняете доступные действия в свой ход. В сетевой комнате состав инвентаря и валюта меняются через торговлю или мастером; чужие листы и контент блокируются.'],['Цель и общий результат','Щёлкните по модели противника, затем выберите действие. Бросок попадания, урон, спасбросок и расход ресурса выполняются автоматически; результат появляется у всех.'],['Торговля','Покупки доступны только в открытых мастером городах. Цена и остаток задаются мастером, купленный предмет добавляется вашему герою.']];return `<section class="view">${heading('ПОМОЩЬ · 5E 2014/2024',isGM()?'Правила мастера':'Правила игрока','Краткое объяснение интерфейса и специальных правил тактической линии. Редакция 2014/2024 выбирается для кампании; спорные трактовки решает мастер.')}<div class="rules-grid">${[...role,...common].map(([t,p])=>`<article class="rule-card"><h3>${esc(t)}</h3><p>${esc(p)}</p><div class="rule-tags"><span>Драконья Сага</span><span>5e · ${state.meta.edition}</span></div></article>`).join('')}</div></section>`}

function openSettings(){const heroes=state.characters.filter(c=>c.role==='hero');modal('Настройки и права','Локальный режим позволяет проверить интерфейс обеих ролей. В сетевой комнате роль подтверждает сервер.',`<div class="form-grid">${formField('Имя участника','seName',state.session.name)}${selectField('Локальная роль','seRole',[['gm','Мастер'],['player','Игрок']],state.session.role,state.session.connected?'disabled':'')}${selectField('Назначенный герой','seHero',[['','Не назначен'],...heroes.map(c=>[c.id,c.name])],state.session.characterId||'',state.session.connected?'disabled':'')}${formField('Масштаб интерфейса','seUi',state.settings.uiScale,'number','min="0.75" max="1.5" step="0.05"')}${formField('Масштаб поля','seBattle',state.settings.battleScale,'number','min="0.7" max="1.6" step="0.05"')}${formField('Общий масштаб моделей','seModel',state.settings.modelScale,'number','min="0.5" max="1.8" step="0.05"')}${formField('Ширина панели боя','sePanel',state.settings.panelScale,'number','min="0.75" max="1.5" step="0.05"')}</div><div class="permission-list"><label class="permission-row"><span>Игроки видят разрешённые листы группы<small>Личные и GM-листы всё равно скрыты</small></span><input class="toggle" id="seParty" type="checkbox" ${state.permissions.partySheetView?'checked':''} ${isGM()?'':'disabled'}></label><label class="permission-row"><span>Разрешить этому устройству редактировать медиатеку<small>Дополнение к полномочиям мастера</small></span><input class="toggle" id="seMedia" type="checkbox" ${canEditMedia()?'checked':''} ${isGM()?'':'disabled'}></label>${isGM()?state.session.members.filter(m=>m.clientId!==state.session.clientId).map(m=>`<div class="permission-row"><span>${esc(m.name)}<small>${m.role==='gm'?'мастер':'игрок'} · герой и право медиатеки</small></span>${m.role==='player'?`<select class="select" data-member-hero="${attr(m.clientId)}"><option value="">Не назначен</option>${heroes.map(h=>`<option value="${h.id}" ${m.characterId===h.id?'selected':''}>${esc(h.name)}</option>`).join('')}</select>`:''}<input class="toggle" data-media-permission="${attr(m.clientId)}" type="checkbox" ${state.permissions.mediaEditors.includes(m.clientId)?'checked':''}></div>`).join(''):''}</div>`,`<button class="danger-btn" data-action="reset-campaign">Новая пустая кампания</button><div class="modal-actions-right"><button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Сохранить</button></div>`,false,()=>{const oldRole=state.session.role;state.session.name=$('#seName').value.trim()||'Участник';state.session.role=$('#seRole').value;state.session.characterId=$('#seHero').value||null;state.settings.uiScale=E.clamp($('#seUi').value,.75,1.5);state.settings.battleScale=E.clamp($('#seBattle').value,.7,1.6);state.settings.modelScale=E.clamp($('#seModel').value,.5,1.8);state.settings.panelScale=E.clamp($('#sePanel').value,.75,1.5);if(oldRole==='gm'){state.permissions.partySheetView=$('#seParty').checked;const has=state.permissions.mediaEditors.includes(state.session.clientId);if($('#seMedia').checked&&!has)state.permissions.mediaEditors.push(state.session.clientId);if(!$('#seMedia').checked&&has)state.permissions.mediaEditors=state.permissions.mediaEditors.filter(x=>x!==state.session.clientId);$$('[data-media-permission]').forEach(input=>{const id=input.dataset.mediaPermission,exists=state.permissions.mediaEditors.includes(id);if(input.checked&&!exists)state.permissions.mediaEditors.push(id);if(!input.checked&&exists)state.permissions.mediaEditors=state.permissions.mediaEditors.filter(x=>x!==id)})}closeModal();commit('Настройки сохранены')})}
function openProfile(){openSettings()}
function openRoom(){modal('Общий стол','Для LAN/Hamachi запустите приложение мастера на доступном адресе. Для интернета нужен публичный HTTPS-адрес сервера.',`<div class="form-grid">${formField('Код комнаты','roCode',state.session.roomCode||Math.random().toString(36).slice(2,8).toUpperCase())}${selectField('Роль запроса','roRole',[['gm','Мастер комнаты'],['player','Игрок']],state.session.role)}${selectField('Герой игрока','roHero',[['','Не выбран'],...state.characters.filter(c=>c.role==='hero').map(c=>[c.id,c.name])],state.session.characterId||'')}</div><div class="help-callout">На этом сервере адрес API совпадает с адресом приложения. Код комнаты можно безопасно передать участникам; ключ владельца хранится только локально.</div><div class="member-list">${state.session.members.map(m=>`<span><i class="${m.role==='gm'?'gm':''}"></i>${esc(m.name)} · ${m.role==='gm'?'мастер':'игрок'}</span>`).join('')||'<span>Нет подключённых участников</span>'}</div>`,`${state.session.connected?'<button class="danger-btn" data-action="disconnect-room">Отключиться</button>':'<button class="dark-btn" data-close>Отмена</button>'}<button class="primary" data-action="connect-room">${state.session.connected?'Переподключиться':'Подключиться'}</button>`,false,null)}
async function connectRoom(){const code=$('#roCode')?.value.trim().toUpperCase();if(!code)return toast('Введите код комнаты');const role=$('#roRole').value,characterId=$('#roHero').value||null;try{const res=await fetch(`/api/rooms/${encodeURIComponent(code)}/session`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({clientId:state.session.clientId,name:state.session.name,role,characterId,sessionToken:state.session.token,ownerKey:state.session.ownerKey})});const data=await res.json();if(!res.ok)throw new Error(data.error||'Ошибка сервера');state.session={...state.session,roomCode:code,token:data.token,ownerKey:data.ownerKey||state.session.ownerKey,role:data.role,characterId:data.characterId,connected:true};net={revision:data.revision||0,eventSource:null,pushing:false};if(data.state)acceptRemote(data.state);else if(data.role==='gm')await pushRoom(true);startEvents();closeModal();commit(data.warning||`Подключено к столу ${code}`,false);render()}catch(err){toast('Не удалось подключиться',err.message)}}
function acceptRemote(remote){const localSession=state.session;state=normalize(remote);state.session={...state.session,...localSession,connected:true,members:remote.network?.members||remote.session?.members||[]}}
function startEvents(){net?.eventSource?.close();const es=new EventSource(`/api/rooms/${encodeURIComponent(state.session.roomCode)}/events?token=${encodeURIComponent(state.session.token)}`);net.eventSource=es;es.onmessage=e=>{try{const data=JSON.parse(e.data);if(data.revision<=net.revision)return;net.revision=data.revision;if(data.state){acceptRemote(data.state);saveLocal();render()}}catch{}};es.onerror=()=>{$('#syncStatus span').textContent='Переподключение…'}}
async function pushRoom(force=false){if(!state.session.connected||net?.pushing)return;net.pushing=true;try{const res=await fetch(`/api/rooms/${encodeURIComponent(state.session.roomCode)}/state`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${state.session.token}`},body:JSON.stringify({state,baseRevision:net.revision})});const data=await res.json();if(res.status===409&&data.state){net.revision=data.revision;acceptRemote(data.state);render();toast('Состояние обновлено','Получена более новая версия комнаты.')}else if(!res.ok)throw new Error(data.error||'Синхронизация не выполнена');else{net.revision=data.revision;if(data.state)acceptRemote(data.state)}}catch(err){if(!force)toast('Ошибка синхронизации',err.message)}finally{net.pushing=false}}
async function disconnectRoom(){try{await fetch(`/api/rooms/${encodeURIComponent(state.session.roomCode)}/session`,{method:'DELETE',headers:{Authorization:`Bearer ${state.session.token}`}})}catch{}net?.eventSource?.close();net=null;state.session.connected=false;state.session.members=[];closeModal();commit('Сетевое соединение закрыто')}
async function assignMember(clientId,characterId){if(!isGM()||!state.session.connected||!net)return;try{const response=await fetch(`/api/rooms/${encodeURIComponent(state.session.roomCode)}/assignment`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.session.token}`},body:JSON.stringify({clientId,characterId:characterId||null})}),data=await response.json();if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);net.revision=data.revision;state.session.members=data.members||state.session.members;toast('Владение обновлено',characterId?'Герой назначен игроку':'Игрок больше не привязан к герою')}catch(error){toast('Назначение не выполнено',error.message)}}
function exportMod(){const pack={format:'dragon-saga-mod',version:1,manifest:{name:`${state.meta.title} — мод`,author:state.session.name,createdAt:now(),appVersion:'2.2.0'},content:clone(state.content),assets:clone(state.assets),theme:clone(state.settings.theme),animations:clone(state.settings.animation),localization:clone(state.settings.localization)};const blob=new Blob([JSON.stringify(pack,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='dragon-saga-mod.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importMod(file){try{const pack=JSON.parse(await file.text());if(pack?.format!=='dragon-saga-mod'||!pack.content||!Array.isArray(pack.assets))throw new Error('Неверный формат dragon-saga-mod');const assetMap=new Map();for(const a of pack.assets){const old=a.id,id=E.id();assetMap.set(old,id);state.assets.push({...a,id,createdAt:now(),createdBy:state.session.clientId})}for(const type of ['items','actions','creatures','mods'])for(const x of pack.content[type]||[])state.content[type].push({...x,id:E.id(),importedFrom:pack.manifest?.name||'mod'});if(pack.theme&&typeof pack.theme==='object')state.settings.theme={...state.settings.theme,...pack.theme};if(pack.animations&&typeof pack.animations==='object')state.settings.animation={...state.settings.animation,...pack.animations};if(pack.localization&&typeof pack.localization==='object')state.settings.localization={...state.settings.localization,...pack.localization};state.content.mods.push({id:E.id(),name:pack.manifest?.name||file.name,description:`Импортирован пакет · ${pack.assets.length} материалов`,manifest:pack.manifest||{}});commit('Мод-пакет импортирован')}catch(err){toast('Мод отклонён',err.message)}}
function quickDice(){modal('Быстрый бросок','Криптографически случайные кости; результат можно записать в общий боевой журнал.',`<div class="dice-row">${[4,6,8,10,12,20,100].map(d=>`<button class="die-btn" data-die="${d}">к${d}</button>`).join('')}</div><div class="custom-roll"><input id="modalRoll" class="text-input" value="1d20+0"><button class="primary" data-action="modal-roll">Бросить</button></div><div id="rollResult" class="help-callout">Выберите кость или формулу.</div>`,`<button class="dark-btn" data-close>Закрыть</button>`,false,null)}
function rollAndShow(expr,where='#rollResult'){try{const r=E.rollExpression(expr);const out=$(where);if(out)out.innerHTML=`<b>${r.total}</b><br>${esc(r.expression)} · ${esc(r.detail)}`;logBattle(state.session.name,`бросок ${r.expression}: ${r.total} (${r.detail})`);setDirty();return r}catch(err){toast('Ошибка формулы',err.message)}}
async function exportCampaign(){const safe=clone(state);safe.session={...safe.session,token:'',ownerKey:'',connected:false,members:[]};const content=JSON.stringify(safe,null,2),name=`${state.meta.title.replace(/[^a-zа-я0-9]+/gi,'-').replace(/^-|-$/g,'')||'dragon-saga'}.dragon-saga.json`;if(window.dragonSagaDesktop?.saveCampaign){const r=await window.dragonSagaDesktop.saveCampaign(content,name);if(!r?.canceled)toast('Кампания сохранена',r.path||name);return}const blob=new Blob([content],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function validateImport(raw){if(!raw||raw.schema!=='dragon-saga-campaign')throw new Error('Это не файл кампании «Драконья Сага».');return normalize(raw)}
async function openCampaign(){if(window.dragonSagaDesktop?.openCampaign){const r=await window.dragonSagaDesktop.openCampaign();if(!r?.canceled&&r.data)loadCampaignText(r.data);return}$('#campaignImportInput').click()}
function loadCampaignText(text){try{const incoming=validateImport(JSON.parse(text));const session=state.session;state=incoming;state.session={...state.session,clientId:session.clientId,name:session.name,connected:false,token:'',ownerKey:'',roomCode:'',members:[]};selectedCharacterId=null;currentView='dashboard';saveLocal();render();toast('Кампания открыта',state.meta.title)}catch(err){toast('Импорт отклонён',err.message)}}
function resetCampaign(){if(!confirm('Создать новую пустую кампанию? Сначала экспортируйте текущую, если она нужна.'))return;const identity={clientId:state.session.clientId,name:state.session.name,role:'gm'};state=baseState();Object.assign(state.session,identity);selectedCharacterId=null;closeModal();commit('Создана новая пустая кампания')}
function openBossTelegraph(id){const boss=state.characters.find(x=>x.id===id);if(!boss)return;modal('Подготовка босса','Подготовка видна всем. Проверки Восприятия или Анализа не расходуют основное действие.',`${formField('Название особого действия','btName','Сокрушительный замысел')}${selectField('Природа','btNature',[['martial','Боевая / физическая'],['magical','Магическая']],boss.telegraph?.nature||'martial')}<label class="form-field"><span>Видимый намёк</span><textarea class="text-area" id="btHint">${esc(boss.telegraph?.hint||'Босс явно готовит опасное действие.')}</textarea></label><label class="form-field"><span>Контрмера при успехе проверки</span><textarea class="text-area" id="btCounter">${esc(boss.telegraph?.counter||'')}</textarea></label>`,`<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Объявить подготовку</button>`,false,()=>{boss.boss=true;boss.telegraph={name:$('#btName').value.trim()||'Особое действие',nature:$('#btNature').value,hint:$('#btHint').value,counter:$('#btCounter').value,stage:'prepared',round:state.battle.round};logBattle(boss.name,`ПОДГОТАВЛИВАЕТ: ${boss.telegraph.name}. ${boss.telegraph.hint}`,'warn');setResult(`${boss.name} готовит: ${boss.telegraph.name}`,null);closeModal();nextTurn()})}
function showSource(id){const c=state.characters.find(x=>x.id===id);modal('Исходный текст',c?.name||'',c?.sourceText?`<pre style="white-space:pre-wrap;color:#b8c4c8;font-size:11px">${esc(c.sourceText)}</pre>`:'<p class="micro">Этот лист создан вручную; исходного импорта нет.</p>','<button class="dark-btn" data-close>Закрыть</button>',true)}
function showAudit(id){const c=state.characters.find(x=>x.id===id);modal('Аудит импорта',c?.name||'',`<div class="audit-list">${c?.audit?.length?c.audit.map(x=>`<span class="${x.status}"><b>${esc(x.label)}</b> — ${esc(x.note)}</span>`).join(''):'<span>Лист создан вручную.</span>'}</div>`,'<button class="dark-btn" data-close>Закрыть</button>')}
function previewImport(){const text=$('#importText')?.value||'';if(!text.trim())return;const r=E.parseCharacterText(text,state.meta.edition);$('#importPreview').innerHTML=`<div class="audit-list">${r.character.audit.map(x=>`<span class="${x.status}"><b>${esc(x.label)}</b> — ${esc(x.note)}</span>`).join('')}</div><div class="help-callout">Предпросмотр: <b>${esc(r.character.name)}</b>, КД ${r.character.ac}, ОЗ ${r.character.hp}/${r.character.maxHp}, действий ${r.character.actions.length}. Исходный текст будет сохранён полностью.</div>`}
function bindDynamic(){const input=$('#assetInput');if(input)input.onchange=e=>importAssets([...e.target.files]);const modInput=$('#modInput');if(modInput)modInput.onchange=e=>{if(e.target.files[0])importMod(e.target.files[0])};if(currentView==='scene'){mountSceneModels();if(isGM())bindSceneDrag()}}
function bindSceneDrag(){const stage=$('#sceneStage'),scene=state.scenes.find(x=>x.id===selectedSceneId);if(!stage||!scene)return;stage.querySelectorAll('[data-object]').forEach(el=>{let start=null;el.addEventListener('pointerdown',e=>{if(e.target.matches('button'))return;start={x:e.clientX,y:e.clientY,left:parseFloat(el.style.left),top:parseFloat(el.style.top)};el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!start)return;const r=stage.getBoundingClientRect(),o=scene.objects.find(x=>x.id===el.dataset.object);o.x=E.clamp(start.left+(e.clientX-start.x)/r.width*100,0,100);o.y=E.clamp(start.top+(e.clientY-start.y)/r.height*100,0,100);el.style.left=o.x+'%';el.style.top=o.y+'%'});el.addEventListener('pointerup',()=>{if(start){start=null;setDirty()}});el.addEventListener('wheel',e=>{e.preventDefault();const o=scene.objects.find(x=>x.id===el.dataset.object);o.scale=E.clamp(o.scale+(e.deltaY<0?2:-2),5,100);el.style.width=o.scale+'%';setDirty()},{passive:false})})}

document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-action],[data-character],[data-select-character],[data-target]');if(!b)return;
 if(b.matches('[data-close]'))return closeModal();if(b.matches('[data-modal-submit]'))return modalHandler?.();
 if(b.dataset.view){currentView=b.dataset.view;return render()}if(b.dataset.character){selectedCharacterId=b.dataset.character;currentView='characters';return render()}if(b.dataset.selectCharacter){selectedCharacterId=b.dataset.selectCharacter;return render()}if(b.dataset.target){state.battle.targetId=b.dataset.target;return render()}
 if(b.dataset.context){contextTab=b.dataset.context;return render()}if(b.dataset.mediaTab){mediaTab=b.dataset.mediaTab;return render()}if(b.dataset.workshopTab){workshopTab=b.dataset.workshopTab;return render()}if(b.dataset.map){selectedMap=b.dataset.map;return render()}if(b.dataset.scene){selectedSceneId=b.dataset.scene;return render()}
 if(b.dataset.hp){const c=state.characters.find(x=>x.id===b.dataset.id);if(c&&canEditCharacter(c)){c.hp=E.clamp(c.hp+Number(b.dataset.hp),0,c.maxHp);commit()};return}
 if(b.dataset.resource){const c=state.characters.find(x=>x.id===b.dataset.char),r=c?.resources.find(x=>x.id===b.dataset.id);if(r&&canEditCharacter(c)){r.current=E.clamp(r.current+Number(b.dataset.resource),0,r.max);commit()};return}
 if(b.dataset.move)return moveActor(b.dataset.id,Number(b.dataset.move));if(b.dataset.die){const input=$('#modalRoll');if(input){input.value=`1d${b.dataset.die}`;return rollAndShow(input.value)}return rollAndShow(`1d${b.dataset.die}`,'#notThere')}
 if(b.dataset.combatAction){const actor=state.characters.find(x=>x.id===b.dataset.actor),a=actor?.actions.find(x=>x.id===b.dataset.combatAction),target=state.characters.find(x=>x.id===state.battle.targetId)||(a?.targetSide==='self'?actor:null);return resolveAction(actor,a,target)}
 if(b.dataset.investigate){const actor=state.characters.find(x=>x.id===b.dataset.actor),boss=state.characters.find(x=>x.id===b.dataset.boss);return investigateBoss(actor,boss,b.dataset.investigate)}
 if(b.dataset.removeCombatant){removeCombatant(b.dataset.removeCombatant);closeModal();return openBattleSetup()}
 if(b.dataset.deleteChronicle){state.journal.chronicle=state.journal.chronicle.filter(x=>x.id!==b.dataset.deleteChronicle);return commit('Запись удалена')}
 if(b.dataset.editRoute)return openRoute(b.dataset.editRoute);if(b.dataset.deleteRoute){state.world.routes=state.world.routes.filter(x=>x.id!==b.dataset.deleteRoute);return commit('Маршрут удалён')}
 if(b.dataset.editLocation)return editLocation(b.dataset.editLocation);if(b.dataset.editCity)return openCity(b.dataset.editCity);if(b.dataset.newMerchant)return openMerchant(b.dataset.newMerchant);if(b.dataset.editMerchant)return editMerchant(b.dataset.editMerchant);if(b.dataset.newStock)return openStock(b.dataset.newStock);if(b.dataset.buy)return buyItem(b.dataset.buy);if(b.dataset.sell)return sellItem(b.dataset.sell);
 if(b.dataset.deleteCity&&confirm('Удалить город и всех его торговцев?')){state.cities=state.cities.filter(x=>x.id!==b.dataset.deleteCity);return commit('Город удалён')}
 if(b.dataset.deleteMerchant&&confirm('Удалить торговца и весь его прилавок?')){const[cid,mid]=b.dataset.deleteMerchant.split(':'),city=state.cities.find(x=>x.id===cid);if(city){city.merchants=city.merchants.filter(x=>x.id!==mid);return commit('Торговец удалён')}}
 if(b.dataset.editStock)return openStock(b.dataset.editStock);if(b.dataset.deleteStock){const[cid,mid,iid]=b.dataset.deleteStock.split(':'),m=state.cities.find(x=>x.id===cid)?.merchants.find(x=>x.id===mid);if(m){m.stock=m.stock.filter(x=>x.id!==iid);commit('Товар удалён')}return}
 if(b.dataset.deleteAsset){if(!confirm('Удалить материал? Ссылки на него в сценах перестанут отображаться.'))return;state.assets=state.assets.filter(x=>x.id!==b.dataset.deleteAsset);return commit('Материал удалён')}
 if(b.dataset.playAsset){const a=assetById(b.dataset.playAsset);if(a?.data)new Audio(a.data).play().catch(err=>toast('Звук не запущен',err.message));return}
 if(b.dataset.deleteContent){const[type,id]=b.dataset.deleteContent.split(':');state.content[type]=state.content[type].filter(x=>x.id!==id);return commit('Запись удалена')}
 if(b.dataset.deleteObject){const s=state.scenes.find(x=>x.id===selectedSceneId);s.objects=s.objects.filter(x=>x.id!==b.dataset.deleteObject);return commit('Объект удалён')}
 if(b.dataset.editScene&&isGM())return openScene(b.dataset.editScene);if(b.dataset.deleteScene&&isGM()&&confirm('Удалить сцену и все размещённые объекты?')){state.scenes=state.scenes.filter(x=>x.id!==b.dataset.deleteScene);if(state.battle.sceneId===b.dataset.deleteScene)state.battle.sceneId=null;selectedSceneId=state.scenes[0]?.id||null;return commit('Сцена удалена')}
 const action=b.dataset.action;if(!action)return;
 const map={
  'new-character':()=>openCharacterEditor(),'edit-character':()=>openCharacterEditor(state.characters.find(x=>x.id===b.dataset.id)),'import-character':openImport,
  'new-action':()=>openActionEditor(b.dataset.id),'edit-action':()=>openActionEditor(b.dataset.char,b.dataset.id),'new-resource':()=>openResourceEditor(b.dataset.id),'new-item':()=>openItemEditor(b.dataset.id),'edit-item':()=>openItemEditor(b.dataset.char,b.dataset.id),'delete-item':()=>{const c=state.characters.find(x=>x.id===b.dataset.char);if(state.session.connected&&!isGM())return toast('В сетевой комнате состав инвентаря меняют мастер или торговля');if(c&&confirm('Удалить предмет?')){c.inventory=c.inventory.filter(x=>x.id!==b.dataset.id);for(const slot of Object.keys(c.equipment))if(c.equipment[slot]===b.dataset.id)c.equipment[slot]=null;closeModal();commit('Предмет удалён')}},'show-source':()=>showSource(b.dataset.id),'show-audit':()=>showAudit(b.dataset.id),'preview-import':previewImport,
  'delete-character':()=>{if(confirm('Удалить лист?')){state.characters=state.characters.filter(x=>x.id!==b.dataset.id);removeCombatant(b.dataset.id);selectedCharacterId=null}},
  'battle-setup':openBattleSetup,'start-battle':startBattle,'end-battle':endBattle,'next-turn':nextTurn,
  'disengage':()=>disengageActor(state.characters.find(x=>x.id===b.dataset.id)),
  'flank':()=>moveActor(b.dataset.id,0,'flank'),'breather':()=>tacticalBreather(state.characters.find(x=>x.id===b.dataset.id)),'boss-telegraph':()=>openBossTelegraph(b.dataset.id),
  'custom-roll':()=>rollAndShow($('#customRoll').value,'#notThere'),'modal-roll':()=>rollAndShow($('#modalRoll').value),
  'chronicle-add':openChronicle,'save-journal':()=>{if(isGM())state.journal.party=$('#journalText').value;else state.journal.personal[state.session.characterId]=$('#journalText').value;commit('Журнал сохранён')},
  'new-route':openRoute,'new-city':openCity,'new-scene':openScene,'add-scene-object':()=>{const s=state.scenes.find(x=>x.id===b.dataset.id),aid=$('#sceneAsset').value;if(!aid)return toast('Выберите изображение');s.objects.push({id:E.id(),assetId:aid,x:50,y:50,scale:24,rotation:0,z:s.objects.length});commit('Объект размещён')},
  'upload-assets':()=>$('#assetInput')?.click(),'workshop-add':openWorkshopItem,'import-mod':()=>$('#modInput')?.click(),'export-mod':exportMod,'connect-room':connectRoom,'disconnect-room':disconnectRoom,'reset-campaign':resetCampaign
 };map[action]?.()});

document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-member-hero]'))assignMember(t.dataset.memberHero,t.value||null);if(t.matches('[data-scene-bg]')){const s=state.scenes.find(x=>x.id===t.dataset.sceneBg);s.backgroundAsset=t.value||null;commit('Фон сцены обновлён')}if(t.matches('[data-scene-battle]')){state.battle.sceneId=t.checked?t.dataset.sceneBattle:null;commit('Активная сцена обновлена')}});
$('#campaignTitle').addEventListener('click',()=>{modal('Название кампании','Используется в заголовке и имени файла сохранения.',formField('Название','campaignName',state.meta.title),'<button class="dark-btn" data-close>Отмена</button><button class="primary" data-modal-submit>Сохранить</button>',false,()=>{state.meta.title=$('#campaignName').value.trim()||'Новая сага';closeModal();commit('Кампания переименована')})});
$$('[data-edition]').forEach(b=>b.addEventListener('click',()=>{state.meta.edition=b.dataset.edition;commit(`Редакция ${b.dataset.edition}`)}));
$('#quickDiceBtn').addEventListener('click',quickDice);$('#settingsBtn').addEventListener('click',openSettings);$('#profileBtn').addEventListener('click',openProfile);$('#roomBtn').addEventListener('click',openRoom);$('#saveExportBtn').addEventListener('click',exportCampaign);$('#campaignImportInput').addEventListener('change',async e=>{const f=e.target.files[0];if(f)loadCampaignText(await f.text());e.target.value=''});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();exportCampaign()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='o'){e.preventDefault();openCampaign()}});
document.addEventListener('dragon-saga-image-save',e=>{if(!canEditMedia())return toast('Нет права сохранять в медиатеку');const d=e.detail;if(!d?.blob)return;const reader=new FileReader();reader.onload=()=>{state.assets.push({id:E.id(),name:d.title||d.name||'Изображение',kind:'image',mime:d.mime||d.blob.type,size:d.blob.size,data:reader.result,width:d.width,height:d.height,createdAt:now(),createdBy:state.session.clientId});commit('Изображение сохранено в медиатеку')};reader.readAsDataURL(d.blob)});
window.dragonSagaDesktop?.onCommand?.(action=>({save:exportCampaign,'save-as':exportCampaign,open:openCampaign,new:resetCampaign,settings:openSettings,room:openRoom}[action]?.()));
window.addEventListener('beforeunload',()=>{saveLocal();net?.eventSource?.close()});
render();
})();
